window.PRACTICE_QUESTIONS = {"version": "2026-10-15.2", "attribution": "Created by Mrs Knox", "notice": "Original practice questions. Marks and marking points are indicative, not official QCAA marking schemes. This starter bank samples topics; it is not a complete paper or complete syllabus coverage. Model responses show one supported approach.", "questions": [{"id": "legal-referendum", "template": "referendum", "subject": "legal", "title": "Applying referendum requirements", "scopes": {"unit3": {"route": "legal", "topics": ["Referendums and constitutional change"]}}, "question": "A proposal to alter the Australian Constitution receives 54% of the national vote and a majority in three states.\n\nDetermine whether the referendum succeeds. Justify your response using the double-majority requirement.", "answer": ["No. A successful constitutional referendum requires a national majority and a majority in at least four of the six states. The national requirement is met, but the state requirement is not."], "points": [{"text": "Correct conclusion: does not pass", "marks": 1}, {"text": "National majority is met", "marks": 1}, {"text": "At least four states required; only three support it", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Do not treat the national vote alone as sufficient. Territory votes count towards the national total, not a state majority.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_legal_25_syll.pdf"}, {"label": "Concept reference", "url": "https://peo.gov.au/understand-our-parliament/how-parliament-works/the-australian-constitution/double-majority"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_legal_studies_25_ia1_smple_ass_inst_exam.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_legal_studies_26_subj_rpt_endorse.pdf"}]}, {"id": "legal-government", "template": "government", "subject": "legal", "title": "Representative and responsible government", "scopes": {"unit3": {"route": "legal", "topics": ["Representative and responsible government"]}}, "question": "Explain the difference between representative government and responsible government in Australia.", "answer": ["Representative government means elected representatives make decisions on behalf of the people. Responsible government means the executive is accountable to parliament; a government must maintain the confidence of the lower house."], "points": [{"text": "Accurate explanation of representation", "marks": 1}, {"text": "Accurate explanation of executive accountability/confidence", "marks": 1}, {"text": "Clear distinction using parliamentary terminology", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_legal_25_syll.pdf"}, {"label": "Concept reference", "url": "https://peo.gov.au/understand-our-parliament/how-parliament-works/system-of-government/responsible-government"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_legal_studies_25_ia1_smple_ass_inst_exam.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_legal_studies_26_subj_rpt_endorse.pdf"}]}, {"id": "legal-review", "template": "review", "subject": "legal", "title": "Accountability for executive decisions", "scopes": {"unit3": {"route": "legal", "topics": ["Democracy, the rule of law and government accountability", "Governance issues: viewpoints, consequences and legal alternatives"]}}, "question": "Analyse the issue of accountability for decisions made by the Queensland government agency in Sources 1–3. Examine two viewpoints and their consequences. Evaluate two legal alternatives and justify a recommendation using legal criteria. Discuss one implication of your recommendation.", "answer": ["The issue is accountability for executive decisions: people affected by the agency’s decisions may be unable to obtain reasons or effectively challenge them. Source 1 identifies the scale of unanswered requests and the existing internal review mechanism.", "The community legal service prioritises reasons and independent review. This could improve procedural fairness and people’s ability to challenge errors. The agency administration prioritises resources and timely decisions. Extra reporting and review requirements could increase costs and delay other applications.", "One legal alternative is a statutory duty to give written reasons, with defined exceptions and response deadlines, while retaining internal review. A second is that duty combined with accessible independent review. The first improves transparency at lower administrative cost, but internal review may leave concerns about independence. The second provides a stronger accountability safeguard but requires additional resources.", "A defensible recommendation is reasons plus accessible independent review, justified by procedural fairness and accountability. Fund the review function and set reasonable time limits to address the agency’s resourcing concerns. An implication is additional expenditure and demand for trained reviewers. A different recommendation can earn credit if supported by the sources and legal criteria."], "points": [{"text": "Analyses the nature and scope of the identified governance issue using the sources", "marks": 2}, {"text": "Examines two viewpoints and their consequences", "marks": 4}, {"text": "Evaluates two legal alternatives and justifies a recommendation using legal criteria", "marks": 3}, {"text": "Discusses a relevant implication", "marks": 1}], "marks": 10, "stimulus": "Original fictional Queensland governance sources for practice.\n\nSource 1 — Agency record: A Queensland government agency made 400 decisions in a year. Ninety people asked for reasons. Seventy of these requests received no written response. The agency has an internal review process.\n\nSource 2 — Community legal service statement: “People need to understand a decision before they can challenge it. Review should be accessible and independent of the original decision-maker.”\n\nSource 3 — Agency administration statement: “More reporting and external reviews would require extra staff and funding. The agency must also resolve applications promptly.”", "table": null, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_legal_25_syll.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_legal_studies_25_ia1_smple_ass_inst_exam.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_legal_studies_26_subj_rpt_endorse.pdf"}], "practiceType": "Extended-response skills practice — not a complete IA1 item"}, {"id": "legal-treaty-effect", "template": "treaty-effect", "subject": "legal", "title": "Ratification and domestic law", "scopes": {"ea": {"route": "legal", "topics": ["International treaties", "Ratification, accession and reservations"]}}, "question": "Explain the effect of Australia’s ratification of a human rights treaty on international obligations and enforceability in Australian courts.", "answer": ["Ratification creates international obligations but does not by itself incorporate every provision into Australian domestic law. Existing domestic law may already implement some obligations; otherwise legislation may be needed for domestic legal effect."], "points": [{"text": "Correctly rejects automatic incorporation", "marks": 1}, {"text": "Distinguishes international obligation from domestic enforceability", "marks": 1}, {"text": "Explains existing law and/or implementing legislation", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Do not say ratification has no effect: international obligations and domestic enforceability are different issues.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_legal_25_syll.pdf"}, {"label": "Concept reference", "url": "https://humanrights.gov.au/resource-hub/by-resource-type/education/human-rights-explained/human-rights-explained-australia-and-human-rights-treaties"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_legal_studies_25_ia1_smple_ass_inst_exam.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_legal_studies_26_subj_rpt_endorse.pdf"}]}, {"id": "legal-declaration", "template": "declaration", "subject": "legal", "title": "Declaration and treaty", "scopes": {"ea": {"route": "legal", "topics": ["UDHR, ICCPR and ICESCR"]}}, "question": "Explain one legal difference between the Universal Declaration of Human Rights (UDHR) and the International Covenant on Civil and Political Rights (ICCPR).", "answer": ["The UDHR is a declaration setting out human rights standards; it is not itself a treaty. The ICCPR is a treaty that creates international obligations for states that become parties. This distinction does not mean the UDHR has no legal influence or that a treaty automatically becomes domestic law."], "points": [{"text": "Correctly identifies the UDHR as a declaration", "marks": 1}, {"text": "Correctly identifies the ICCPR as a treaty with obligations for parties", "marks": 1}, {"text": "Explains rather than simply names the difference", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_legal_25_syll.pdf"}, {"label": "Concept reference", "url": "https://www.ohchr.org/en/what-are-human-rights/international-bill-human-rights"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_legal_studies_25_ia1_smple_ass_inst_exam.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_legal_studies_26_subj_rpt_endorse.pdf"}]}, {"id": "legal-rights-reform", "template": "rights-reform", "subject": "legal", "title": "Evaluating access to human rights complaints", "scopes": {"ea": {"route": "legal", "topics": ["Resolving human rights complaints", "Analysing an Australian human rights issue", "Evaluating human rights reform"]}}, "question": "Refer to the complaints-process proposal in the stimulus.\n\n(a) Evaluate the two options using accessibility and fairness. (4 marks)\n\n(b) Justify a recommendation and explain one implication. (2 marks)", "answer": ["Keeping the process limits additional government spending but leaves a documented access barrier. Free independent assistance could help people understand the form and present relevant information, improving accessibility and fairness. A defensible recommendation is funded assistance, with an eligibility or triage process if resources are limited. This requires funding and service capacity; monitor whether abandoned complaints decrease. Other recommendations can earn credit if justified using the criteria and evidence."], "points": [{"text": "Compares both alternatives with the evidence", "marks": 2}, {"text": "Applies accessibility and fairness", "marks": 2}, {"text": "Makes a justified recommendation", "marks": 1}, {"text": "Explains a practical implication", "marks": 1}], "marks": 6, "stimulus": "Original practice data: A complaints body receives 400 attempted online applications. Of these, 120 are abandoned before submission. A survey of 50 people who abandoned an application finds that 30 did not understand the form. Option A keeps the current process. Option B funds free independent assistance. The estimated annual cost of Option B is $200,000.", "table": null, "difficulty": "hard", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_legal_25_syll.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_legal_studies_25_ia1_smple_ass_inst_exam.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_legal_studies_26_subj_rpt_endorse.pdf"}], "partMarks": [4, 2]}, {"id": "economics-fx-v0", "template": "fx", "subject": "economics", "title": "What does an appreciation change?", "scopes": {"unit3": {"route": "economics", "topics": ["Appreciation and depreciation: economic effects"]}}, "question": "The exchange rate changes from US$0.70 to US$0.80 per A$1. A supplier’s price remains US$400.\n\n(a) Calculate the Australian-dollar price before the change. Show working. (1 mark)\n\n(b) Calculate the Australian-dollar price after the change. Show working. (1 mark)\n\n(c) Identify the movement in the Australian dollar and its effect on the import price. (1 mark)", "answer": ["Before: 400 ÷ 0.7 = A$571.43.", "After: 400 ÷ 0.8 = A$500.00.", "The Australian dollar has appreciated: A$1 buys more US dollars. The item becomes cheaper in A$ under the stated fixed-US-price assumption."], "points": [{"text": "Correct initial conversion", "marks": 1}, {"text": "Correct later conversion", "marks": 1}, {"text": "Correctly identifies appreciation and its price effect", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "For a US-dollar price, divide by the US dollars bought by A$1; do not multiply.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_economics_25_syll.pdf"}, {"label": "Concept reference", "url": "https://www.rba.gov.au/education/resources/explainers/exchange-rates-and-the-australian-economy.html"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_economics_25_unit3_ia1_smple_ass_inst.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_economics_26_subj_rpt_endorse.pdf"}], "partMarks": [1, 1, 1], "working": [{"heading": "Conversion formula", "lines": ["Price in A$ = price in US$ ÷ US$ per A$1"]}, {"heading": "Before the change", "lines": ["A$ price = 400 ÷ 0.7", "= A$571.43"]}, {"heading": "After the change", "lines": ["A$ price = 400 ÷ 0.8", "= A$500.00"]}, {"heading": "Interpret", "lines": ["The Australian dollar appreciates because A$1 buys more US dollars.", "The item becomes cheaper in Australian dollars under the fixed-US-price assumption."]}], "answerLayout": "steps"}, {"id": "economics-fx-v1", "template": "fx", "subject": "economics", "title": "What does an appreciation change?", "scopes": {"unit3": {"route": "economics", "topics": ["Appreciation and depreciation: economic effects"]}}, "question": "The exchange rate changes from US$0.60 to US$0.75 per A$1. A supplier’s price remains US$600.\n\n(a) Calculate the Australian-dollar price before the change. Show working. (1 mark)\n\n(b) Calculate the Australian-dollar price after the change. Show working. (1 mark)\n\n(c) Identify the movement in the Australian dollar and its effect on the import price. (1 mark)", "answer": ["Before: 600 ÷ 0.6 = A$1000.00.", "After: 600 ÷ 0.75 = A$800.00.", "The Australian dollar has appreciated: A$1 buys more US dollars. The item becomes cheaper in A$ under the stated fixed-US-price assumption."], "points": [{"text": "Correct initial conversion", "marks": 1}, {"text": "Correct later conversion", "marks": 1}, {"text": "Correctly identifies appreciation and its price effect", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "For a US-dollar price, divide by the US dollars bought by A$1; do not multiply.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_economics_25_syll.pdf"}, {"label": "Concept reference", "url": "https://www.rba.gov.au/education/resources/explainers/exchange-rates-and-the-australian-economy.html"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_economics_25_unit3_ia1_smple_ass_inst.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_economics_26_subj_rpt_endorse.pdf"}], "partMarks": [1, 1, 1], "working": [{"heading": "Conversion formula", "lines": ["Price in A$ = price in US$ ÷ US$ per A$1"]}, {"heading": "Before the change", "lines": ["A$ price = 600 ÷ 0.6", "= A$1000.00"]}, {"heading": "After the change", "lines": ["A$ price = 600 ÷ 0.75", "= A$800.00"]}, {"heading": "Interpret", "lines": ["The Australian dollar appreciates because A$1 buys more US dollars.", "The item becomes cheaper in Australian dollars under the fixed-US-price assumption."]}], "answerLayout": "steps"}, {"id": "economics-fx-v2", "template": "fx", "subject": "economics", "title": "What does an appreciation change?", "scopes": {"unit3": {"route": "economics", "topics": ["Appreciation and depreciation: economic effects"]}}, "question": "The exchange rate changes from US$0.65 to US$0.78 per A$1. A supplier’s price remains US$390.\n\n(a) Calculate the Australian-dollar price before the change. Show working. (1 mark)\n\n(b) Calculate the Australian-dollar price after the change. Show working. (1 mark)\n\n(c) Identify the movement in the Australian dollar and its effect on the import price. (1 mark)", "answer": ["Before: 390 ÷ 0.65 = A$600.00.", "After: 390 ÷ 0.78 = A$500.00.", "The Australian dollar has appreciated: A$1 buys more US dollars. The item becomes cheaper in A$ under the stated fixed-US-price assumption."], "points": [{"text": "Correct initial conversion", "marks": 1}, {"text": "Correct later conversion", "marks": 1}, {"text": "Correctly identifies appreciation and its price effect", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "For a US-dollar price, divide by the US dollars bought by A$1; do not multiply.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_economics_25_syll.pdf"}, {"label": "Concept reference", "url": "https://www.rba.gov.au/education/resources/explainers/exchange-rates-and-the-australian-economy.html"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_economics_25_unit3_ia1_smple_ass_inst.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_economics_26_subj_rpt_endorse.pdf"}], "partMarks": [1, 1, 1], "working": [{"heading": "Conversion formula", "lines": ["Price in A$ = price in US$ ÷ US$ per A$1"]}, {"heading": "Before the change", "lines": ["A$ price = 390 ÷ 0.65", "= A$600.00"]}, {"heading": "After the change", "lines": ["A$ price = 390 ÷ 0.78", "= A$500.00"]}, {"heading": "Interpret", "lines": ["The Australian dollar appreciates because A$1 buys more US dollars.", "The item becomes cheaper in Australian dollars under the fixed-US-price assumption."]}], "answerLayout": "steps"}, {"id": "economics-trade-effects", "template": "trade-effects", "subject": "economics", "title": "Effects of a depreciation", "scopes": {"unit3": {"route": "economics", "topics": ["Appreciation and depreciation: economic effects"]}}, "question": "Explain one benefit and one cost of a depreciation of the Australian dollar. State one condition that could affect these outcomes.", "answer": ["With foreign-currency prices and other factors held constant, Australian exports become cheaper to overseas buyers, potentially increasing export demand and benefiting exporters. Imports become more expensive in A$, raising costs for importers and consumers. The net effect depends on demand responsiveness, contracts, imported inputs and time lags; an improved trade balance is not automatic."], "points": [{"text": "Explains export benefit through relative prices", "marks": 1}, {"text": "Explains import cost through relative prices", "marks": 1}, {"text": "States a relevant limitation", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_economics_25_syll.pdf"}, {"label": "Concept reference", "url": "https://www.rba.gov.au/education/resources/explainers/exchange-rates-and-the-australian-economy.html"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_economics_25_unit3_ia1_smple_ass_inst.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_economics_26_subj_rpt_endorse.pdf"}]}, {"id": "economics-trade-data", "template": "trade-data", "subject": "economics", "title": "Read the trade evidence", "scopes": {"unit3": {"route": "economics", "topics": ["Balance of payments: accounts and relationships", "Trade data: patterns, trends and economic relationships"]}}, "question": "Refer to the trade data.\n\n(a) Calculate the goods trade balance in each year and the change between years. (3 marks)\n\n(b) Explain why the data do not establish the change in the entire current account. (1 mark)", "answer": ["Year 1 goods balance = 80 − 65 = a surplus of $15 billion. Year 2 = 90 − 82 = a surplus of $8 billion. The goods surplus falls by $7 billion. The current account also includes services, primary income and secondary income; these are not supplied."], "points": [{"text": "Calculates both goods balances", "marks": 2}, {"text": "Correct $7 billion decrease", "marks": 1}, {"text": "Explains missing current-account components", "marks": 1}], "marks": 4, "stimulus": "", "table": {"headers": ["$ billion", "Year 1", "Year 2"], "rows": [["Goods exports", 80, 90], ["Goods imports", 65, 82]]}, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_economics_25_syll.pdf"}, {"label": "Concept reference", "url": "https://www.abs.gov.au/statistics/economy/international-trade/balance-payments-and-international-investment-position-australia"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_economics_25_unit3_ia1_smple_ass_inst.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_economics_26_subj_rpt_endorse.pdf"}], "partMarks": [3, 1], "working": [{"heading": "Year 1", "lines": ["Goods balance = exports − imports", "= 80 − 65", "= $15 billion surplus"]}, {"heading": "Year 2", "lines": ["Goods balance = 90 − 82", "= $8 billion surplus"]}, {"heading": "Change", "lines": ["Change = 8 − 15", "= −$7 billion", "The goods surplus decreases by $7 billion."]}, {"heading": "Current-account limitation", "lines": ["The current account also includes services, primary income and secondary income.", "Those data are not supplied."]}], "answerLayout": "steps"}, {"id": "economics-policy-chain", "template": "policy-chain", "subject": "economics", "title": "Trace a monetary-policy effect", "scopes": {"ea": {"route": "economics", "topics": ["Monetary policy and transmission channels"]}}, "question": "Explain how higher interest rates can reduce inflationary pressure through household spending. Explain one reason this effect may be delayed or uneven.", "answer": ["Higher lending rates can increase repayments for borrowers and make new borrowing less attractive. Some households reduce consumption, lowering aggregate demand and demand-driven inflationary pressure. Effects vary because some loans have fixed rates, households differ in debt and savings, and decisions take time. Savers may receive more interest income."], "points": [{"text": "Explains a borrowing/cash-flow channel", "marks": 1}, {"text": "Links lower consumption to lower aggregate demand", "marks": 1}, {"text": "Links demand to inflationary pressure", "marks": 1}, {"text": "Explains one lag or uneven effect", "marks": 1}], "marks": 4, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_economics_25_syll.pdf"}, {"label": "Concept reference", "url": "https://www.rba.gov.au/education/resources/explainers/the-transmission-of-monetary-policy.html"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_economics_25_unit3_ia1_smple_ass_inst.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_economics_26_subj_rpt_endorse.pdf"}]}, {"id": "economics-nominal-real", "template": "nominal-real", "subject": "economics", "title": "Real and nominal growth", "scopes": {"ea": {"route": "economics", "topics": ["Real and nominal measures"]}}, "question": "Nominal GDP increases by 8% and the GDP price index increases by 5%.\n\nCalculate real GDP growth using the exact index method. Show working.", "answer": ["Real growth factor = 1.08 ÷ 1.05 = 1.028571… . Real GDP growth ≈ 2.86%. Subtracting gives an approximation of 3%, but the exact index method adjusts multiplicatively."], "points": [{"text": "Uses nominal growth factor divided by price growth factor", "marks": 1}, {"text": "Correct percentage ≈ 2.86%", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_economics_25_syll.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_economics_25_unit3_ia1_smple_ass_inst.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_economics_26_subj_rpt_endorse.pdf"}], "working": [{"heading": "Growth factors", "lines": ["Nominal GDP factor = 1.08", "Price factor = 1.05"]}, {"heading": "Real growth factor", "lines": ["Real factor = nominal factor / price factor", "= 1.08/1.05", "= 1.028571…"]}, {"heading": "Convert to percentage growth", "lines": ["Real growth = (1.028571… − 1) × 100", "Real GDP growth ≈ 2.86%"]}], "answerLayout": "steps"}, {"id": "economics-policy-judgement", "template": "policy-judgement", "subject": "economics", "title": "Evaluating employment policy", "scopes": {"ea": {"route": "economics", "topics": ["Supply-side policies and microeconomic reform", "Policy limitations and trade-offs", "Evaluating economic policy"]}}, "question": "Analyse the employment effects of the two policies in the stimulus. Evaluate which policy should be prioritised using one economic criterion. Justify your decision and explain one limitation.", "answer": ["The stated skills mismatch suggests structural barriers to employment. Training could increase workers’ suitability for available jobs. A temporary rebate could increase consumption and derived demand for labour sooner, but does not directly supply the missing qualifications.", "Using employment as the economic criterion, prioritising targeted training is a defensible decision because it addresses the stated mismatch and may support sustained employment. Training takes time and must match employer needs; it does not guarantee jobs. Prioritising the rebate could also earn credit if the decision uses one relevant criterion, the evidence and a justified causal explanation."], "points": [{"text": "Uses the skills-mismatch evidence", "marks": 1}, {"text": "Compares the policies through employment effects", "marks": 2}, {"text": "Makes and justifies a decision using one economic criterion", "marks": 1}, {"text": "Explains a limitation or trade-off", "marks": 1}], "marks": 5, "stimulus": "Original practice scenario: Unemployment is 6.5%, but regional employers report vacancies requiring qualifications that many jobseekers do not hold. Government can fund either a two-year targeted training program or a temporary rebate on household purchases. Assume the same initial budget for either option.", "table": null, "difficulty": "hard", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_economics_25_syll.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_economics_25_unit3_ia1_smple_ass_inst.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_economics_26_subj_rpt_endorse.pdf"}]}, {"id": "business-expansion", "template": "expansion", "subject": "business", "title": "Evaluating market-entry options", "scopes": {"unit3": {"route": "business", "topics": ["Domestic and global expansion strategies and modes of entry", "Financing options for expansion"]}}, "question": "Evaluate the two market-entry options for the business using control and financial exposure. Make a justified decision and recommend how the business should proceed.", "answer": ["A wholly owned outlet gives greater control over staff, service and brand presentation but places the $800,000 investment and operating risk on the business. Licensing needs less direct investment but gives less day-to-day control and requires monitoring the licensee. Given the $250,000 available budget, licensing is a defensible recommendation if brand standards and oversight are enforceable. A wholly owned outlet would require a justified financing plan."], "points": [{"text": "Explains control difference", "marks": 1}, {"text": "Explains financing/risk difference using figures", "marks": 1}, {"text": "Makes a feasible recommendation", "marks": 1}, {"text": "Justifies it using both criteria", "marks": 1}], "marks": 4, "stimulus": "Original practice scenario: A mature Australian business wants to enter a new overseas market. A wholly owned outlet needs $800,000 upfront. Licensing needs $100,000 for training, contracts and monitoring. The business has $250,000 available and wants consistent service quality.", "table": null, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_business_25_syll.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_business_25_unit3_ia1_smple_ass_inst.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_business_26_subj_rpt_endorse.pdf"}]}, {"id": "business-swot", "template": "swot", "subject": "business", "title": "Applying SWOT analysis", "scopes": {"unit3": {"route": "business", "topics": ["SWOT and power interest grid analysis"]}}, "question": "Refer to the business stimulus.\n\n(a) Identify one internal strength and one external threat for a SWOT analysis. (2 marks)\n\n(b) Explain one implication for expansion. (1 mark)", "answer": ["An experienced multilingual service team is an internal strength because it is a resource within the business. A new overseas competitor is an external threat. Expansion may use the team’s language capability, but the competitor makes differentiation and market research important; simply entering the market does not ensure sales."], "points": [{"text": "Correct internal strength", "marks": 1}, {"text": "Correct external threat", "marks": 1}, {"text": "Evidence-based implication", "marks": 1}], "marks": 3, "stimulus": "Original practice scenario: The firm has an experienced multilingual service team. Its existing cash reserve is small. A new overseas competitor has entered its proposed expansion market, while demand in that market is growing.", "table": null, "difficulty": "easy", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_business_25_syll.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_business_25_unit3_ia1_smple_ass_inst.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_business_26_subj_rpt_endorse.pdf"}], "partMarks": [2, 1]}, {"id": "business-change-data", "template": "change-data", "subject": "business", "title": "Evaluating a business transformation", "scopes": {"ea": {"route": "business", "topics": ["Business renewal and transformation", "Resistance to change", "Performance management in renewal", "Evaluating transformation strategies"]}}, "question": "Evaluate the business transformation using productivity and employee retention. Use the data to justify a decision about its effectiveness and recommend one refinement.", "answer": ["Output per worker rises from 20 to 26 units, a 30% increase, suggesting improved productivity. Staff turnover rises from 8% to 18%, a 10-percentage-point increase, suggesting a retention problem. The result is mixed: higher output is accompanied by greater staff loss. One refinement is staff consultation and targeted training/support, followed by monitoring both productivity and turnover. The before/after data alone do not establish that the new system caused every change."], "points": [{"text": "Correct productivity calculation and interpretation", "marks": 2}, {"text": "Correct retention interpretation", "marks": 1}, {"text": "Balanced judgement using both criteria", "marks": 1}, {"text": "Justified refinement", "marks": 1}], "marks": 5, "stimulus": "", "table": {"headers": ["Measure", "Before", "After"], "rows": [["Units per worker per day", 20, 26], ["Annual staff turnover", "8%", "18%"]]}, "difficulty": "hard", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_business_25_syll.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_business_25_unit3_ia1_smple_ass_inst.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_business_26_subj_rpt_endorse.pdf"}]}, {"id": "accounting-depreciation-v0", "template": "depreciation", "subject": "accounting", "title": "Straight-line depreciation", "scopes": {"unit3": {"route": "accounting", "topics": ["Straight-line and diminishing-balance depreciation"]}}, "question": "An asset costs $24,000, has a residual value of $4,000 and a useful life of 5 years. Ignore GST and impairment.\n\n(a) Calculate annual straight-line depreciation. (1 mark)\n\n(b) Calculate accumulated depreciation and carrying amount after two complete years. (2 marks)", "answer": ["Annual depreciation = (cost − residual value) ÷ useful life = (24000 − 4000) ÷ 5 = $4,000.", "Accumulated depreciation after two years = $8,000. Carrying amount = 24000 − 8,000 = $16,000."], "points": [{"text": "Correct annual depreciation", "marks": 1}, {"text": "Correct accumulated depreciation", "marks": 1}, {"text": "Correct carrying amount", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_accounting_25_syll.pdf"}], "partMarks": [1, 2], "working": [{"heading": "Annual depreciation", "lines": ["Depreciation = (cost − residual value) / useful life", "= (24,000 − 4,000) / 5", "= $4,000 per year"]}, {"heading": "Accumulated depreciation", "lines": ["= 2 × $4,000", "= $8,000"]}, {"heading": "Carrying amount", "lines": ["Carrying amount = cost − accumulated depreciation", "= $24,000 − $8,000", "= $16,000"]}], "answerLayout": "steps"}, {"id": "accounting-depreciation-v1", "template": "depreciation", "subject": "accounting", "title": "Straight-line depreciation", "scopes": {"unit3": {"route": "accounting", "topics": ["Straight-line and diminishing-balance depreciation"]}}, "question": "An asset costs $18,000, has a residual value of $3,000 and a useful life of 6 years. Ignore GST and impairment.\n\n(a) Calculate annual straight-line depreciation. (1 mark)\n\n(b) Calculate accumulated depreciation and carrying amount after two complete years. (2 marks)", "answer": ["Annual depreciation = (cost − residual value) ÷ useful life = (18000 − 3000) ÷ 6 = $2,500.", "Accumulated depreciation after two years = $5,000. Carrying amount = 18000 − 5,000 = $13,000."], "points": [{"text": "Correct annual depreciation", "marks": 1}, {"text": "Correct accumulated depreciation", "marks": 1}, {"text": "Correct carrying amount", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_accounting_25_syll.pdf"}], "partMarks": [1, 2], "working": [{"heading": "Annual depreciation", "lines": ["Depreciation = (cost − residual value) / useful life", "= (18,000 − 3,000) / 6", "= $2,500 per year"]}, {"heading": "Accumulated depreciation", "lines": ["= 2 × $2,500", "= $5,000"]}, {"heading": "Carrying amount", "lines": ["Carrying amount = cost − accumulated depreciation", "= $18,000 − $5,000", "= $13,000"]}], "answerLayout": "steps"}, {"id": "accounting-depreciation-v2", "template": "depreciation", "subject": "accounting", "title": "Straight-line depreciation", "scopes": {"unit3": {"route": "accounting", "topics": ["Straight-line and diminishing-balance depreciation"]}}, "question": "An asset costs $36,000, has a residual value of $6,000 and a useful life of 5 years. Ignore GST and impairment.\n\n(a) Calculate annual straight-line depreciation. (1 mark)\n\n(b) Calculate accumulated depreciation and carrying amount after two complete years. (2 marks)", "answer": ["Annual depreciation = (cost − residual value) ÷ useful life = (36000 − 6000) ÷ 5 = $6,000.", "Accumulated depreciation after two years = $12,000. Carrying amount = 36000 − 12,000 = $24,000."], "points": [{"text": "Correct annual depreciation", "marks": 1}, {"text": "Correct accumulated depreciation", "marks": 1}, {"text": "Correct carrying amount", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_accounting_25_syll.pdf"}], "partMarks": [1, 2], "working": [{"heading": "Annual depreciation", "lines": ["Depreciation = (cost − residual value) / useful life", "= (36,000 − 6,000) / 5", "= $6,000 per year"]}, {"heading": "Accumulated depreciation", "lines": ["= 2 × $6,000", "= $12,000"]}, {"heading": "Carrying amount", "lines": ["Carrying amount = cost − accumulated depreciation", "= $36,000 − $12,000", "= $24,000"]}], "answerLayout": "steps"}, {"id": "accounting-disposal", "template": "disposal", "subject": "accounting", "title": "Gain or loss on disposal", "scopes": {"unit3": {"route": "accounting", "topics": ["Disposal of non-current assets and gain or loss"]}}, "question": "An asset cost $30,000 and has accumulated depreciation of $19,000. It is sold for $9,500. Ignore GST and selling costs.\n\nCalculate the gain or loss on disposal. Show working.", "answer": ["Carrying amount = 30,000 − 19,000 = $11,000. Proceeds are $9,500, so there is a $1,500 loss on disposal."], "points": [{"text": "Correct carrying amount", "marks": 1}, {"text": "Correct amount and classification as loss", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_accounting_25_syll.pdf"}], "working": [{"heading": "Carrying amount", "lines": ["Carrying amount = cost − accumulated depreciation", "= $30,000 − $19,000", "= $11,000"]}, {"heading": "Disposal result", "lines": ["Gain/loss = proceeds − carrying amount", "= $9,500 − $11,000", "= −$1,500", "The business records a $1,500 loss."]}], "answerLayout": "steps"}, {"id": "accounting-accrual", "template": "accrual", "subject": "accounting", "title": "A balance-day adjustment", "scopes": {"ea": {"route": "accounting", "topics": ["Balance day adjustments", "General journal and ledger"]}}, "question": "At 30 June, unrecorded wages of $1,200 are owed for work already performed.\n\n(a) State the adjusting journal entry. (2 marks)\n\n(b) Explain the effects on profit and current liabilities. (1 mark)", "answer": ["Debit Wages expense $1,200; credit Wages payable (or accrued wages) $1,200. Recognising the expense decreases profit by $1,200; the unpaid obligation increases current liabilities by $1,200. Cash is unchanged at this point."], "points": [{"text": "Correct debit", "marks": 1}, {"text": "Correct credit", "marks": 1}, {"text": "Correct profit and liability effects", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_accounting_25_syll.pdf"}], "partMarks": [2, 1]}, {"id": "accounting-ratios", "template": "ratios", "subject": "accounting", "title": "Profitability and liquidity", "scopes": {"ea": {"route": "accounting", "topics": ["Profitability ratios", "Liquidity and stability ratios"]}}, "question": "Refer to the financial data.\n\n(a) Calculate net profit margin and current ratio. (2 marks)\n\n(b) Explain why sales do not establish the business’s ability to pay short-term debts. (2 marks)", "answer": ["Net profit margin = 36,000 ÷ 300,000 × 100 = 12%. Current ratio = 90,000 ÷ 60,000 = 1.5:1. The first ratio concerns profit relative to revenue; the second compares current assets with current liabilities. Sales may be on credit and current assets may include inventory, so timing and composition of assets matter for paying debts."], "points": [{"text": "Correct margin", "marks": 1}, {"text": "Correct current ratio", "marks": 1}, {"text": "Distinguishes profitability from short-term liquidity with a reason", "marks": 2}], "marks": 4, "stimulus": "Original practice financial data: revenue $300,000; net profit $36,000; current assets $90,000; current liabilities $60,000.", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_accounting_25_syll.pdf"}], "partMarks": [2, 2], "working": [{"heading": "Net profit margin", "lines": ["Margin = (net profit / revenue) × 100", "= (36,000/300,000) × 100", "= 12%"]}, {"heading": "Current ratio", "lines": ["Current ratio = current assets / current liabilities", "= 90,000/60,000", "= 1.5 : 1"]}, {"heading": "Interpret", "lines": ["Profitability concerns profit relative to revenue; liquidity concerns short-term obligations.", "Credit sales may not yet generate cash, and current assets may include inventory.", "The timing and composition of current assets matter."]}], "answerLayout": "steps"}, {"id": "maths_general-regression-v0", "template": "regression", "subject": "maths_general", "title": "Prediction and residual", "scopes": {"unit3": {"route": "maths_general", "topics": ["Bivariate data analysis 2"]}, "ea": {"route": "maths_general", "topics": ["Least-squares regression and residuals"]}}, "question": "A fitted model and an observation are given:\nŷ = 8 + 2.5x\nx = 6\nObserved y = 25\n\n(a) Calculate the predicted value of y. (1 mark)\n\n(b) Calculate the residual using observed − predicted. (1 mark)", "answer": ["Predicted y = 8 + 2.5 × 6 = 23.", "Residual = 25 − 23 = 2."], "points": [{"text": "Correct prediction", "marks": 1}, {"text": "Correct signed residual", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_general_25_syll.pdf"}], "working": [{"heading": "Predicted value", "lines": ["ŷ = 8 + 2.5x", "ŷ = 8 + 2.5 × 6", "ŷ = 23"]}, {"heading": "Residual", "lines": ["Residual = observed − predicted", "Residual = 25 − 23", "Residual = 2"]}], "answerLayout": "steps", "partMarks": [1, 1]}, {"id": "maths_general-regression-v1", "template": "regression", "subject": "maths_general", "title": "Prediction and residual", "scopes": {"unit3": {"route": "maths_general", "topics": ["Bivariate data analysis 2"]}, "ea": {"route": "maths_general", "topics": ["Least-squares regression and residuals"]}}, "question": "A fitted model and an observation are given:\nŷ = 4 + 3x\nx = 8\nObserved y = 30\n\n(a) Calculate the predicted value of y. (1 mark)\n\n(b) Calculate the residual using observed − predicted. (1 mark)", "answer": ["Predicted y = 4 + 3 × 8 = 28.", "Residual = 30 − 28 = 2."], "points": [{"text": "Correct prediction", "marks": 1}, {"text": "Correct signed residual", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_general_25_syll.pdf"}], "working": [{"heading": "Predicted value", "lines": ["ŷ = 4 + 3x", "ŷ = 4 + 3 × 8", "ŷ = 28"]}, {"heading": "Residual", "lines": ["Residual = observed − predicted", "Residual = 30 − 28", "Residual = 2"]}], "answerLayout": "steps", "partMarks": [1, 1]}, {"id": "maths_general-regression-v2", "template": "regression", "subject": "maths_general", "title": "Prediction and residual", "scopes": {"unit3": {"route": "maths_general", "topics": ["Bivariate data analysis 2"]}, "ea": {"route": "maths_general", "topics": ["Least-squares regression and residuals"]}}, "question": "A fitted model and an observation are given:\nŷ = 15 + 1.2x\nx = 10\nObserved y = 24\n\n(a) Calculate the predicted value of y. (1 mark)\n\n(b) Calculate the residual using observed − predicted. (1 mark)", "answer": ["Predicted y = 15 + 1.2 × 10 = 27.", "Residual = 24 − 27 = -3."], "points": [{"text": "Correct prediction", "marks": 1}, {"text": "Correct signed residual", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_general_25_syll.pdf"}], "working": [{"heading": "Predicted value", "lines": ["ŷ = 15 + 1.2x", "ŷ = 15 + 1.2 × 10", "ŷ = 27"]}, {"heading": "Residual", "lines": ["Residual = observed − predicted", "Residual = 24 − 27", "Residual = -3"]}], "answerLayout": "steps", "partMarks": [1, 1]}, {"id": "maths_general-sequence-v0", "template": "sequence", "subject": "maths_general", "title": "Use the term number correctly", "scopes": {"unit3": {"route": "maths_general", "topics": ["Growth and decay in sequences"]}, "ea": {"route": "maths_general", "topics": ["Arithmetic and geometric sequences"]}}, "question": "A geometric sequence has:\nfirst term a = 200\ncommon ratio r = 1.05.\n\nCalculate term 4. Give your answer to two decimal places.", "answer": ["u_n = a × r^(n−1). Therefore u_4 = 200 × 1.05^3 = 231.53."], "points": [{"text": "Correct exponent n−1", "marks": 1}, {"text": "Correct value and rounding", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_general_25_syll.pdf"}], "working": [{"heading": "Formula", "lines": ["uₙ = arⁿ⁻¹"]}, {"heading": "Substitute", "lines": ["u4 = 200 × 1.05^(4 − 1)", "u4 = 200 × 1.05^3"]}, {"heading": "Calculate", "lines": ["u4 = 231.53 (to 2 decimal places)"]}], "answerLayout": "steps"}, {"id": "maths_general-sequence-v1", "template": "sequence", "subject": "maths_general", "title": "Use the term number correctly", "scopes": {"unit3": {"route": "maths_general", "topics": ["Growth and decay in sequences"]}, "ea": {"route": "maths_general", "topics": ["Arithmetic and geometric sequences"]}}, "question": "A geometric sequence has:\nfirst term a = 500\ncommon ratio r = 0.9.\n\nCalculate term 3. Give your answer to two decimal places.", "answer": ["u_n = a × r^(n−1). Therefore u_3 = 500 × 0.9^2 = 405.00."], "points": [{"text": "Correct exponent n−1", "marks": 1}, {"text": "Correct value and rounding", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_general_25_syll.pdf"}], "working": [{"heading": "Formula", "lines": ["uₙ = arⁿ⁻¹"]}, {"heading": "Substitute", "lines": ["u3 = 500 × 0.9^(3 − 1)", "u3 = 500 × 0.9^2"]}, {"heading": "Calculate", "lines": ["u3 = 405.00 (to 2 decimal places)"]}], "answerLayout": "steps"}, {"id": "maths_general-sequence-v2", "template": "sequence", "subject": "maths_general", "title": "Use the term number correctly", "scopes": {"unit3": {"route": "maths_general", "topics": ["Growth and decay in sequences"]}, "ea": {"route": "maths_general", "topics": ["Arithmetic and geometric sequences"]}}, "question": "A geometric sequence has:\nfirst term a = 120\ncommon ratio r = 1.1.\n\nCalculate term 5. Give your answer to two decimal places.", "answer": ["u_n = a × r^(n−1). Therefore u_5 = 120 × 1.1^4 = 175.69."], "points": [{"text": "Correct exponent n−1", "marks": 1}, {"text": "Correct value and rounding", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_general_25_syll.pdf"}], "working": [{"heading": "Formula", "lines": ["uₙ = arⁿ⁻¹"]}, {"heading": "Substitute", "lines": ["u5 = 120 × 1.1^(5 − 1)", "u5 = 120 × 1.1^4"]}, {"heading": "Calculate", "lines": ["u5 = 175.69 (to 2 decimal places)"]}], "answerLayout": "steps"}, {"id": "maths_general-seasonal", "template": "seasonal", "subject": "maths_general", "title": "Seasonally adjusted sales", "scopes": {"unit3": {"route": "maths_general", "topics": ["Time series analysis"]}, "ea": {"route": "maths_general", "topics": ["Time series and seasonal indices"]}}, "question": "Sales in one quarter are 240 units. Its seasonal index is 1.20. Calculate seasonally adjusted sales and interpret the index.", "answer": ["Seasonally adjusted sales = 240 ÷ 1.20 = 200 units. An index of 1.20 indicates that this quarter is typically 20% above the underlying level because of its seasonal effect."], "points": [{"text": "Divides by the index", "marks": 1}, {"text": "Correct 200 units", "marks": 1}, {"text": "Correct interpretation of 1.20", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_general_25_syll.pdf"}], "working": [{"heading": "Formula", "lines": ["Seasonally adjusted value = observed value ÷ seasonal index"]}, {"heading": "Substitute and calculate", "lines": ["= 240 ÷ 1.20", "= 200 units"]}, {"heading": "Interpret", "lines": ["The quarter is typically 20% above the underlying level because of seasonality."]}], "answerLayout": "steps"}, {"id": "maths_general-timezones", "template": "timezones", "subject": "maths_general", "title": "Cross the date boundary", "scopes": {"unit3": {"route": "maths_general", "topics": ["Earth geometry and time zones"]}, "ea": {"route": "maths_general", "topics": ["Earth geometry and time zones"]}}, "question": "City A uses UTC+10 and City B uses UTC−5 on the date in question. It is 08:00 Monday in City A. What is the time and day in City B? Ignore daylight saving.", "answer": ["City B is 15 hours behind City A. 08:00 Monday − 15 hours = 17:00 Sunday."], "points": [{"text": "Correct 15-hour difference and direction", "marks": 1}, {"text": "Correct 17:00 Sunday", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_general_25_syll.pdf"}], "working": [{"heading": "Time difference", "lines": ["UTC offsets: +10 and −5", "Difference = 10 − (−5) = 15 hours", "City B is 15 hours behind City A."]}, {"heading": "Apply the difference", "lines": ["08:00 Monday − 15 hours", "= 17:00 Sunday in City B"]}], "answerLayout": "steps"}, {"id": "maths_general-association", "template": "association", "subject": "maths_general", "title": "Association and causation", "scopes": {"unit3": {"route": "maths_general", "topics": ["Bivariate data analysis 1"]}, "ea": {"route": "maths_general", "topics": ["Bivariate associations"]}}, "question": "A school survey finds a positive association between hours of tutoring and exam scores. Explain why this does not establish that tutoring caused the higher scores. Identify a possible confounding factor.", "answer": ["The survey is observational and does not isolate tutoring from other influences. Students with tutoring may differ in prior achievement, motivation, available time or access to resources. A specific confounder could affect both tutoring participation and scores, so the association alone does not establish causation."], "points": [{"text": "Recognises observational association is insufficient", "marks": 1}, {"text": "Identifies a plausible confounder and its role", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_general_25_syll.pdf"}], "working": [{"heading": "Identify the evidence", "lines": ["The survey establishes an association between tutoring hours and scores."]}, {"heading": "Explain the limitation", "lines": ["An observational survey does not isolate tutoring from other influences."]}, {"heading": "Give a confounder", "lines": ["Prior achievement or motivation could affect both tutoring participation and exam scores.", "The association alone does not establish causation."]}], "answerLayout": "steps"}, {"id": "maths_general-networks", "template": "networks", "subject": "maths_general", "title": "Critical path", "scopes": {"ea": {"route": "maths_general", "topics": ["Critical path analysis"]}}, "question": "Activities A (3 days) and B (5 days) start together. C (4 days) follows A. D (2 days) follows both B and C. Find the shortest project duration, the critical path and the float of B.", "answer": ["A→C finishes at day 7; B finishes at day 5. D starts at day 7 and finishes at day 9. Minimum duration is 9 days. The critical path is A–C–D. B can finish as late as day 7, so its float is 2 days."], "points": [{"text": "Correct 9-day duration", "marks": 1}, {"text": "Correct critical path", "marks": 1}, {"text": "Correct B float", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_general_25_syll.pdf"}], "working": [{"heading": "Earliest finishes", "lines": ["A finishes at day 3.", "B finishes at day 5.", "C finishes at day 3 + 4 = 7."]}, {"heading": "Final activity", "lines": ["D can start only after both B and C.", "D starts at max(5, 7) = day 7.", "D finishes at day 7 + 2 = day 9."]}, {"heading": "Critical path and float", "lines": ["Critical path: A → C → D", "Duration = 3 + 4 + 2 = 9 days", "B can finish by day 7 without delaying D.", "Float of B = 7 − 5 = 2 days"]}], "answerLayout": "steps"}, {"id": "maths_general-interest", "template": "interest", "subject": "maths_general", "title": "Compound growth", "scopes": {"ea": {"route": "maths_general", "topics": ["Compound-interest loans and investments"]}}, "question": "Invest $5,000 for three years at 4% compounded annually, with no deposits or withdrawals. Calculate the final balance to the nearest cent.", "answer": ["A = 5000 × 1.04³ = $5,624.32."], "points": [{"text": "Correct compound-interest expression", "marks": 1}, {"text": "Correct final balance", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_general_25_syll.pdf"}], "working": [{"heading": "Formula", "lines": ["A = P(1 + r)ⁿ"]}, {"heading": "Substitute", "lines": ["A = 5000(1 + 0.04)³", "A = 5000 × 1.04³"]}, {"heading": "Final balance", "lines": ["A = $5,624.32"]}], "answerLayout": "steps"}, {"id": "maths_methods-exponential-v0", "template": "exponential", "subject": "maths_methods", "title": "Differentiate an exponential", "scopes": {"unit3": {"route": "maths_methods", "topics": ["Differentiation of exponential and logarithmic functions"]}, "ea": {"route": "maths_methods", "topics": ["Differentiating exponential and logarithmic functions"]}}, "question": "Differentiate the function:\nf(x) = e^(2x) + ln(x), for x > 0.", "answer": ["f′(x) = 2e^(2x) + 1/x. The exponential term requires the chain rule."], "points": [{"text": "Correct chain-rule exponential derivative", "marks": 1}, {"text": "Correct logarithmic derivative", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_methods_25_syll.pdf"}], "working": [{"heading": "Differentiate the exponential", "lines": ["For e^(u), the derivative is u′e^(u).", "u = 2x, so u′ = 2.", "d/dx[e^(2x)] = 2e^(2x)"]}, {"heading": "Differentiate the logarithm", "lines": ["d/dx[ln(x)] = 1/x"]}, {"heading": "Combine", "lines": ["f′(x) = 2e^(2x) + 1/x, for x > 0"]}], "answerLayout": "steps"}, {"id": "maths_methods-exponential-v1", "template": "exponential", "subject": "maths_methods", "title": "Differentiate an exponential", "scopes": {"unit3": {"route": "maths_methods", "topics": ["Differentiation of exponential and logarithmic functions"]}, "ea": {"route": "maths_methods", "topics": ["Differentiating exponential and logarithmic functions"]}}, "question": "Differentiate the function:\nf(x) = e^(3x) + ln(x), for x > 0.", "answer": ["f′(x) = 3e^(3x) + 1/x. The exponential term requires the chain rule."], "points": [{"text": "Correct chain-rule exponential derivative", "marks": 1}, {"text": "Correct logarithmic derivative", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_methods_25_syll.pdf"}], "working": [{"heading": "Differentiate the exponential", "lines": ["For e^(u), the derivative is u′e^(u).", "u = 3x, so u′ = 3.", "d/dx[e^(3x)] = 3e^(3x)"]}, {"heading": "Differentiate the logarithm", "lines": ["d/dx[ln(x)] = 1/x"]}, {"heading": "Combine", "lines": ["f′(x) = 3e^(3x) + 1/x, for x > 0"]}], "answerLayout": "steps"}, {"id": "maths_methods-exponential-v2", "template": "exponential", "subject": "maths_methods", "title": "Differentiate an exponential", "scopes": {"unit3": {"route": "maths_methods", "topics": ["Differentiation of exponential and logarithmic functions"]}, "ea": {"route": "maths_methods", "topics": ["Differentiating exponential and logarithmic functions"]}}, "question": "Differentiate the function:\nf(x) = e^(5x) + ln(x), for x > 0.", "answer": ["f′(x) = 5e^(5x) + 1/x. The exponential term requires the chain rule."], "points": [{"text": "Correct chain-rule exponential derivative", "marks": 1}, {"text": "Correct logarithmic derivative", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_methods_25_syll.pdf"}], "working": [{"heading": "Differentiate the exponential", "lines": ["For e^(u), the derivative is u′e^(u).", "u = 5x, so u′ = 5.", "d/dx[e^(5x)] = 5e^(5x)"]}, {"heading": "Differentiate the logarithm", "lines": ["d/dx[ln(x)] = 1/x"]}, {"heading": "Combine", "lines": ["f′(x) = 5e^(5x) + 1/x, for x > 0"]}], "answerLayout": "steps"}, {"id": "maths_methods-trig", "template": "trig", "subject": "maths_methods", "title": "Product rule", "scopes": {"unit3": {"route": "maths_methods", "topics": ["Differentiation of trigonometric functions and differentiation rules"]}, "ea": {"route": "maths_methods", "topics": ["Trigonometric derivatives and differentiation rules"]}}, "question": "Differentiate the function:\nf(x) = x² sin(x).\n\nUse radians.", "answer": ["f′(x) = 2x sin(x) + x² cos(x), by the product rule."], "points": [{"text": "Both product-rule contributions present", "marks": 1}, {"text": "Correct full derivative", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_methods_25_syll.pdf"}], "working": [{"heading": "Choose the rule", "lines": ["u = x², v = sin(x)", "u′ = 2x, v′ = cos(x)", "f′(x) = u′v + uv′"]}, {"heading": "Substitute", "lines": ["f′(x) = (2x)sin(x) + x²cos(x)"]}, {"heading": "Final derivative", "lines": ["f′(x) = 2x sin(x) + x² cos(x)"]}], "answerLayout": "steps"}, {"id": "maths_methods-stationary", "template": "stationary", "subject": "maths_methods", "title": "Classify the stationary point", "scopes": {"unit3": {"route": "maths_methods", "topics": ["Further applications of differentiation"]}, "ea": {"route": "maths_methods", "topics": ["Second derivatives and curve sketching"]}}, "question": "The function is:\nf(x) = x² − 6x + 5.\n\nFind and classify its stationary point. Show working.", "answer": ["f′(x)=2x−6=0 gives x=3. f(3)=−4. Since f″(x)=2>0, (3,−4) is a local minimum."], "points": [{"text": "Correct stationary x", "marks": 1}, {"text": "Correct y-coordinate", "marks": 1}, {"text": "Correct classification with justification", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_methods_25_syll.pdf"}], "working": [{"heading": "Differentiate", "lines": ["f′(x) = 2x − 6"]}, {"heading": "Find the stationary value", "lines": ["2x − 6 = 0", "x = 3"]}, {"heading": "Find the coordinate", "lines": ["f(3) = 3² − 6(3) + 5", "f(3) = −4"]}, {"heading": "Classify", "lines": ["f″(x) = 2 > 0", "The stationary point (3, −4) is a local minimum."]}], "answerLayout": "steps"}, {"id": "maths_methods-integral", "template": "integral", "subject": "maths_methods", "title": "An initial condition", "scopes": {"unit3": {"route": "maths_methods", "topics": ["Further integration"]}, "ea": {"route": "maths_methods", "topics": ["Antiderivatives and initial conditions"]}}, "question": "Given:\nf′(x) = 6x² − 4\nf(1) = 5\n\nFind f(x). Show working.", "answer": ["Integrating gives f(x)=2x³−4x+C. The condition gives 5=2−4+C, so C=7. Therefore f(x)=2x³−4x+7."], "points": [{"text": "Correct antiderivative including C", "marks": 1}, {"text": "Uses initial condition to obtain C=7", "marks": 1}, {"text": "Correct final function", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_methods_25_syll.pdf"}], "working": [{"heading": "Integrate", "lines": ["f(x) = ∫(6x² − 4) dx", "f(x) = 2x³ − 4x + C"]}, {"heading": "Apply f(1) = 5", "lines": ["5 = 2(1)³ − 4(1) + C", "5 = −2 + C", "C = 7"]}, {"heading": "State the function", "lines": ["f(x) = 2x³ − 4x + 7"]}], "answerLayout": "steps"}, {"id": "maths_methods-discrete", "template": "discrete", "subject": "maths_methods", "title": "Expected value", "scopes": {"unit3": {"route": "maths_methods", "topics": ["Discrete random variables"]}, "ea": {"route": "maths_methods", "topics": ["Discrete and binomial distributions"]}}, "question": "The distribution of X is:\nP(X = 0) = 0.2\nP(X = 1) = 0.5\nP(X = 2) = 0.3\n\n(a) Calculate E(X). (1 mark)\n\n(b) Calculate P(X ≥ 1). (1 mark)", "answer": ["E(X)=0×0.2+1×0.5+2×0.3=1.1. P(X≥1)=0.5+0.3=0.8."], "points": [{"text": "Correct expectation calculation", "marks": 1}, {"text": "Correct probability", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_methods_25_syll.pdf"}], "working": [{"heading": "Expected value", "lines": ["E(X) = ΣxP(X = x)", "E(X) = 0(0.2) + 1(0.5) + 2(0.3)", "E(X) = 1.1"]}, {"heading": "Required probability", "lines": ["P(X ≥ 1) = P(X = 1) + P(X = 2)", "= 0.5 + 0.3", "= 0.8"]}], "answerLayout": "steps", "partMarks": [1, 1]}, {"id": "maths_methods-normal", "template": "normal", "subject": "maths_methods", "title": "Standardise and interpret", "scopes": {"ea": {"route": "maths_methods", "topics": ["Normal distributions"]}}, "question": "X is normally distributed with:\nμ = 50\nσ = 8\n\nUse Φ(1.5) = 0.9332.\n\n(a) Calculate the z-score for X = 62. (1 mark)\n\n(b) Calculate P(X > 62). Show working. (2 marks)", "answer": ["z=(62−50)/8=1.5. P(X>62)=1−0.9332=0.0668."], "points": [{"text": "Correct z-score", "marks": 1}, {"text": "Uses upper tail", "marks": 1}, {"text": "Correct probability", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_methods_25_syll.pdf"}], "working": [{"heading": "Standardise", "lines": ["z = (x − μ)/σ", "z = (62 − 50)/8", "z = 1.5"]}, {"heading": "Use the upper tail", "lines": ["P(X > 62) = P(Z > 1.5)", "= 1 − Φ(1.5)", "= 1 − 0.9332", "= 0.0668"]}], "answerLayout": "steps", "partMarks": [1, 2]}, {"id": "maths_methods-ci", "template": "ci", "subject": "maths_methods", "title": "A confidence interval", "scopes": {"ea": {"route": "maths_methods", "topics": ["Confidence intervals for proportions"]}}, "question": "A random sample of 400 people contains 240 supporters of a proposal.\n\nUse the formula:\np̂ ± 1.96√[p̂(1 − p̂)/n]\n\nCalculate an approximate 95% confidence interval for the population proportion. Show working.", "answer": ["p-hat=240/400=0.60. Standard error=√(0.6×0.4/400)≈0.024495. Margin≈0.04801. Interval≈[0.5520,0.6480], or 55.20% to 64.80%."], "points": [{"text": "Correct sample proportion", "marks": 1}, {"text": "Correct standard error/margin", "marks": 1}, {"text": "Correct interval", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "hard", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_methods_25_syll.pdf"}], "working": [{"heading": "Sample proportion", "lines": ["p̂ = 240/400 = 0.60"]}, {"heading": "Standard error", "lines": ["SE = √[p̂(1 − p̂)/n]", "SE = √[(0.60)(0.40)/400]", "SE ≈ 0.024495"]}, {"heading": "Margin of error", "lines": ["ME = 1.96 × SE", "ME ≈ 0.04801"]}, {"heading": "Confidence interval", "lines": ["p̂ ± ME = 0.60 ± 0.04801", "Approximate 95% interval: [0.5520, 0.6480]", "Equivalent to approximately 55.20% to 64.80%."]}], "answerLayout": "steps"}, {"id": "maths_specialist-complex", "template": "complex", "subject": "maths_specialist", "title": "De Moivre’s theorem", "scopes": {"unit3": {"route": "maths_specialist", "topics": ["Further complex numbers"]}, "ea": {"route": "maths_specialist", "topics": ["Complex numbers and De Moivre's theorem"]}}, "question": "Write (1+i)^4 in Cartesian form.", "answer": ["1+i=√2[cos(π/4)+i sin(π/4)]. The fourth power is 4[cos(π)+i sin(π)]=−4. Expanding algebraically is also valid."], "points": [{"text": "Valid method", "marks": 1}, {"text": "Correct −4", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_specialist_25_syll.pdf"}], "working": [{"heading": "Polar form", "lines": ["1 + i = √2[cos(π/4) + i sin(π/4)]"]}, {"heading": "Apply De Moivre’s theorem", "lines": ["(1 + i)⁴ = (√2)⁴[cos(4π/4) + i sin(4π/4)]", "= 4[cos(π) + i sin(π)]"]}, {"heading": "Cartesian form", "lines": ["= 4(−1 + 0i)", "= −4"]}], "answerLayout": "steps"}, {"id": "maths_specialist-induction", "template": "induction", "subject": "maths_specialist", "title": "Complete an induction argument", "scopes": {"unit3": {"route": "maths_specialist", "topics": ["Mathematical induction and trigonometric proofs"]}, "ea": {"route": "maths_specialist", "topics": ["Mathematical induction"]}}, "question": "Prove by mathematical induction that 1+2+…+n=n(n+1)/2 for every positive integer n.", "answer": ["Base case n=1: both sides equal 1. Assume true for n=k: sum to k=k(k+1)/2. Then sum to k+1=k(k+1)/2+(k+1)=(k+1)(k+2)/2. This is the required formula for k+1, so the result holds for all positive integers by induction."], "points": [{"text": "Correct base case", "marks": 1}, {"text": "States the induction hypothesis", "marks": 1}, {"text": "Correct k→k+1 algebra", "marks": 1}, {"text": "Concludes for all positive integers", "marks": 1}], "marks": 4, "stimulus": "", "table": null, "difficulty": "hard", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_specialist_25_syll.pdf"}], "working": [{"heading": "Base case: n = 1", "lines": ["Left side = 1", "Right side = 1(1 + 1)/2 = 1", "The statement is true for n = 1."]}, {"heading": "Induction hypothesis", "lines": ["Assume 1 + 2 + … + k = k(k + 1)/2 for a positive integer k."]}, {"heading": "Inductive step", "lines": ["1 + 2 + … + k + (k + 1)", "= k(k + 1)/2 + (k + 1)", "= (k + 1)(k + 2)/2", "This is the required formula for n = k + 1."]}, {"heading": "Conclusion", "lines": ["The statement holds for every positive integer n by mathematical induction."]}], "answerLayout": "steps"}, {"id": "maths_specialist-vectors", "template": "vectors", "subject": "maths_specialist", "title": "Projection", "scopes": {"unit3": {"route": "maths_specialist", "topics": ["Vectors in two and three dimensions"]}, "ea": {"route": "maths_specialist", "topics": ["Vectors and projections in three dimensions"]}}, "question": "Given:\na = (2, 1, 2)\nb = (1, 0, 1)\n\n(a) Calculate a · b. (1 mark)\n\n(b) Calculate the vector projection of a onto b. (2 marks)", "answer": ["a·b=2+0+2=4. b·b=2. proj_b(a)=[(a·b)/(b·b)]b=2(1,0,1)=(2,0,2)."], "points": [{"text": "Correct dot product", "marks": 1}, {"text": "Correct projection method", "marks": 1}, {"text": "Correct projected vector", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_specialist_25_syll.pdf"}], "working": [{"heading": "Dot products", "lines": ["a · b = 2(1) + 1(0) + 2(1) = 4", "b · b = 1² + 0² + 1² = 2"]}, {"heading": "Projection formula", "lines": ["proj_b(a) = [(a · b)/(b · b)]b"]}, {"heading": "Substitute and simplify", "lines": ["= (4/2)(1, 0, 1)", "= (2, 0, 2)"]}], "answerLayout": "steps", "partMarks": [1, 2]}, {"id": "maths_specialist-vector-calculus", "template": "vector-calculus", "subject": "maths_specialist", "title": "Velocity and acceleration", "scopes": {"unit3": {"route": "maths_specialist", "topics": ["Vector calculus"]}, "ea": {"route": "maths_specialist", "topics": ["Vector calculus"]}}, "question": "A particle has position:\nr(t) = (t², 3t, t³).\n\n(a) Determine its velocity at t = 2. Show the velocity function. (2 marks)\n\n(b) Determine its acceleration at t = 2. (1 mark)", "answer": ["v(t)=(2t,3,3t²), so v(2)=(4,3,12). a(t)=(2,0,6t), so a(2)=(2,0,12)."], "points": [{"text": "Correct velocity function", "marks": 1}, {"text": "Correct v(2)", "marks": 1}, {"text": "Correct acceleration and a(2)", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_specialist_25_syll.pdf"}], "working": [{"heading": "Velocity", "lines": ["v(t) = r′(t) = (2t, 3, 3t²)", "v(2) = (4, 3, 12)"]}, {"heading": "Acceleration", "lines": ["a(t) = v′(t) = (2, 0, 6t)", "a(2) = (2, 0, 12)"]}], "answerLayout": "steps", "partMarks": [2, 1]}, {"id": "maths_specialist-matrices", "template": "matrices", "subject": "maths_specialist", "title": "A matrix inverse", "scopes": {"unit3": {"route": "maths_specialist", "topics": ["Further matrices"]}, "ea": {"route": "maths_specialist", "topics": ["Matrices and systems of equations"]}}, "question": "Given A = [[2, 1], [1, 1]]:\n\n(a) Find A⁻¹. (2 marks)\n\n(b) Use A⁻¹ to solve the system 2x + y = 7 and x + y = 4. (1 mark)", "answer": ["det(A)=2×1−1×1=1. A⁻¹=[[1,−1],[−1,2]]. Multiplying A⁻¹ by (7,4) gives (3,1), so x=3 and y=1."], "points": [{"text": "Correct determinant/inverse", "marks": 2}, {"text": "Correct x and y", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_specialist_25_syll.pdf"}], "working": [{"heading": "Determinant", "lines": ["det(A) = 2(1) − 1(1) = 1"]}, {"heading": "Inverse", "lines": ["A⁻¹ = (1/det(A))[[1, −1], [−1, 2]]", "A⁻¹ = [[1, −1], [−1, 2]]"]}, {"heading": "Solve the system", "lines": ["x = 1(7) − 1(4) = 3", "y = −1(7) + 2(4) = 1"]}, {"heading": "Check", "lines": ["2(3) + 1 = 7", "3 + 1 = 4"]}], "answerLayout": "steps", "partMarks": [2, 1]}, {"id": "maths_specialist-ode", "template": "ode", "subject": "maths_specialist", "title": "Solve a differential equation", "scopes": {"ea": {"route": "maths_specialist", "topics": ["Differential equations and rates of change"]}}, "question": "Solve the differential equation:\ndy/dx = 2y\n\nUse the initial condition y(0) = 3.", "answer": ["The general solution is y=Ce^(2x). The initial condition gives C=3, so y=3e^(2x)."], "points": [{"text": "Correct exponential general solution", "marks": 1}, {"text": "Applies the initial condition correctly", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_specialist_25_syll.pdf"}], "working": [{"heading": "Separate variables", "lines": ["dy/y = 2 dx"]}, {"heading": "Integrate", "lines": ["ln|y| = 2x + C₁", "y = Ce^(2x)"]}, {"heading": "Apply y(0) = 3", "lines": ["3 = Ce⁰", "C = 3"]}, {"heading": "State the solution", "lines": ["y = 3e^(2x)"]}], "answerLayout": "steps"}, {"id": "biology-quadrat", "template": "quadrat", "subject": "biology", "title": "Estimate a population", "scopes": {"unit3": {"route": "biology", "topics": ["Biodiversity and populations"]}, "ea": {"route": "biology", "topics": ["Population sampling"]}}, "question": "Five randomly located 1 m² quadrats contain 4, 6, 5, 3 and 7 plants. The habitat covers 200 m² and is assumed uniform.\n\n(a) Calculate mean density and estimate population size. (2 marks)\n\n(b) Explain one sampling limitation. (1 mark)", "answer": ["Mean density=(4+6+5+3+7)/5=5 plants m⁻². Estimated population=5×200=1,000 plants. Five quadrats may not capture spatial variation; increase the number and use a suitable random or stratified design."], "points": [{"text": "Correct mean density", "marks": 1}, {"text": "Correct estimate with units", "marks": 1}, {"text": "Relevant sampling limitation", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_biology_25_syll.pdf"}], "working": [{"heading": "Mean density", "lines": ["Mean = (4 + 6 + 5 + 3 + 7)/5", "= 25/5", "= 5 plants m⁻²"]}, {"heading": "Population estimate", "lines": ["Population ≈ mean density × habitat area", "= 5 × 200", "= 1,000 plants"]}, {"heading": "Sampling limitation", "lines": ["Five quadrats may not capture spatial variation.", "Increase sampling using an appropriate random or stratified design."]}], "answerLayout": "steps", "partMarks": [2, 1]}, {"id": "biology-energy", "template": "energy", "subject": "biology", "title": "Energy transfer", "scopes": {"unit3": {"route": "biology", "topics": ["Functioning ecosystems and succession"]}, "ea": {"route": "biology", "topics": ["Energy flow and nutrient cycles"]}}, "question": "Refer to the energy data.\n\n(a) Calculate the percentage transfer from producers to primary consumers. (1 mark)\n\n(b) Explain why energy transfer is less than 100%. (2 marks)", "answer": ["Transfer=1,500/12,000×100=12.5%. Not all producer biomass is eaten or assimilated; energy is also used in respiration and dissipated as heat. Energy is not recycled through an ecosystem."], "points": [{"text": "Correct percentage calculation", "marks": 1}, {"text": "Uneaten/unassimilated material identified", "marks": 1}, {"text": "Respiration and heat loss explained", "marks": 1}], "marks": 3, "stimulus": "", "table": {"headers": ["Trophic level", "Energy available (kJ m⁻² yr⁻¹)"], "rows": [["Producers", 12000], ["Primary consumers", 1500], ["Secondary consumers", 180]]}, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_biology_25_syll.pdf"}], "working": [{"heading": "Percentage transfer", "lines": ["Transfer = (energy at next level / energy at previous level) × 100", "= (1,500/12,000) × 100", "= 12.5%"]}, {"heading": "Explain the difference", "lines": ["Not all producer biomass is eaten or assimilated.", "Organisms use energy in respiration and dissipate heat.", "Energy flows through ecosystems; it is not recycled."]}], "answerLayout": "steps", "partMarks": [1, 2]}, {"id": "biology-inheritance", "template": "inheritance", "subject": "biology", "title": "An autosomal recessive cross", "scopes": {"ea": {"route": "biology", "topics": ["Inheritance patterns"]}}, "question": "Two unaffected parents are both carriers of an autosomal recessive allele a. Draw or describe the offspring genotype probabilities and the probability of an affected child. Assume simple Mendelian inheritance.", "answer": ["Aa×Aa produces AA:1/4, Aa:1/2, aa:1/4. An affected child must be aa, so the probability is 1/4 (25%) for each pregnancy. Unaffected offspring are not necessarily non-carriers."], "points": [{"text": "Correct parental cross", "marks": 1}, {"text": "Correct genotype probabilities", "marks": 1}, {"text": "Correct affected probability", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_biology_25_syll.pdf"}], "working": [{"heading": "Parental genotypes", "lines": ["Aa × Aa", "Each parent produces A and a gametes with equal probability."]}, {"heading": "Offspring probabilities", "lines": ["AA: 1/4", "Aa: 1/2", "aa: 1/4"]}, {"heading": "Affected phenotype", "lines": ["Only aa offspring are affected.", "P(affected child) = 1/4 = 25% for each pregnancy.", "Unaffected offspring can still be carriers."]}], "answerLayout": "steps"}, {"id": "biology-selection", "template": "selection", "subject": "biology", "title": "Selection acts on variation", "scopes": {"ea": {"route": "biology", "topics": ["Natural selection and genetic drift"]}}, "question": "In a population, some insects already carry a heritable allele that increases survival after pesticide exposure. Explain how repeated use could change allele frequency.", "answer": ["The population has pre-existing heritable variation. Exposure selects among insects: carriers survive and reproduce at a higher rate under these conditions. They pass the allele to offspring, so its frequency can increase over generations. The pesticide does not cause individuals to develop the needed allele because they need it."], "points": [{"text": "Pre-existing heritable variation", "marks": 1}, {"text": "Differential survival and reproduction", "marks": 1}, {"text": "Inheritance and population allele-frequency change", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_biology_25_syll.pdf"}, {"label": "Concept reference", "url": "https://openstax.org/books/biology-2e/pages/19-3-adaptive-evolution"}], "working": [{"heading": "Variation", "lines": ["Some insects already have a heritable allele that increases survival after exposure."]}, {"heading": "Selection", "lines": ["Carriers survive and reproduce at a higher rate in the pesticide environment."]}, {"heading": "Inheritance and population change", "lines": ["Survivors pass the allele to offspring.", "Its frequency can increase over generations.", "Individuals do not develop a needed allele simply because they need it."]}], "answerLayout": "steps"}, {"id": "chemistry-equilibrium", "template": "equilibrium", "subject": "chemistry", "title": "Calculate Kc", "scopes": {"unit3": {"route": "chemistry", "topics": ["Chemical equilibrium systems"]}, "ea": {"route": "chemistry", "topics": ["Equilibrium constants and reaction quotients"]}}, "question": "For the equilibrium:\nH₂(g) + I₂(g) ⇌ 2HI(g)\n\nEquilibrium concentrations are:\n[H₂] = 0.20 mol L⁻¹\n[I₂] = 0.20 mol L⁻¹\n[HI] = 0.80 mol L⁻¹\n\n(a) Calculate Kc. Show the expression and substitution. (2 marks)\n\n(b) Another mixture at the same temperature has Qc = 4. Predict the net reaction direction and justify your response. (1 mark)", "answer": ["Kc=[HI]²/([H₂][I₂])=0.80²/(0.20×0.20)=16. Since Qc<Kc, the net reaction proceeds towards products until equilibrium is reached."], "points": [{"text": "Correct equilibrium expression", "marks": 1}, {"text": "Correct Kc=16", "marks": 1}, {"text": "Correct comparison and product direction", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_chemistry_25_syll.pdf"}], "working": [{"heading": "Equilibrium expression", "lines": ["Kc = [HI]² / ([H₂][I₂])"]}, {"heading": "Substitute", "lines": ["Kc = 0.80² / (0.20 × 0.20)", "Kc = 0.64/0.04", "Kc = 16"]}, {"heading": "Compare Qc with Kc", "lines": ["Qc = 4 < Kc = 16", "The net reaction proceeds towards products until equilibrium is reached."]}], "answerLayout": "steps", "partMarks": [2, 1]}, {"id": "chemistry-redox", "template": "redox", "subject": "chemistry", "title": "A galvanic cell", "scopes": {"unit3": {"route": "chemistry", "topics": ["Oxidation and reduction"]}, "ea": {"route": "chemistry", "topics": ["Galvanic and electrolytic cells", "Electrode potentials and electrolysis"]}}, "question": "A spontaneous Zn–Cu galvanic cell uses these standard reduction potentials:\nCu²⁺/Cu: +0.34 V\nZn²⁺/Zn: −0.76 V\n\n(a) Identify the anode and write its half-equation. (1 mark)\n\n(b) Identify the cathode and write its half-equation. (1 mark)\n\n(c) Calculate E°cell. (1 mark)", "answer": ["Zinc is oxidised at the anode: Zn→Zn²⁺+2e⁻. Copper ions are reduced at the cathode: Cu²⁺+2e⁻→Cu. E°cell=E°cathode−E°anode=0.34−(−0.76)=+1.10 V."], "points": [{"text": "Correct anode and oxidation", "marks": 1}, {"text": "Correct cathode and reduction", "marks": 1}, {"text": "Correct potential subtraction", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_chemistry_25_syll.pdf"}, {"label": "Concept reference", "url": "https://openstax.org/books/chemistry/pages/17-2-galvanic-cells"}], "working": [{"heading": "Identify the electrodes", "lines": ["Anode: zinc, where oxidation occurs.", "Zn(s) → Zn²⁺(aq) + 2e⁻", "Cathode: copper, where reduction occurs.", "Cu²⁺(aq) + 2e⁻ → Cu(s)"]}, {"heading": "Cell potential", "lines": ["E°cell = E°cathode − E°anode", "= +0.34 − (−0.76)", "= +1.10 V"]}], "answerLayout": "steps", "partMarks": [1, 1, 1]}, {"id": "chemistry-organic", "template": "organic", "subject": "chemistry", "title": "Distinguish structural isomers", "scopes": {"ea": {"route": "chemistry", "topics": ["Organic families and nomenclature", "Structural and stereoisomers"]}}, "question": "Give the condensed structural formulas of the two alcohol structural isomers with molecular formula C₃H₈O. Explain why they are structural isomers.", "answer": ["Propan-1-ol: CH₃CH₂CH₂OH. Propan-2-ol: CH₃CH(OH)CH₃. They have the same molecular formula but different atom connectivity (the hydroxyl group is attached at a different carbon). An ether also has this molecular formula, but the question asks for alcohols."], "points": [{"text": "Correct propan-1-ol", "marks": 1}, {"text": "Correct propan-2-ol", "marks": 1}, {"text": "Correct connectivity explanation", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_chemistry_25_syll.pdf"}], "working": [{"heading": "Name and formula", "lines": ["Propan-1-ol: CH₃CH₂CH₂OH", "Propan-2-ol: CH₃CH(OH)CH₃"]}, {"heading": "Explain isomerism", "lines": ["Both have molecular formula C₃H₈O.", "The hydroxyl group is attached to a different carbon, so connectivity differs.", "An ether with the same formula is outside the question’s alcohol requirement."]}], "answerLayout": "steps"}, {"id": "physics-circular", "template": "circular", "subject": "physics", "title": "Find centripetal force", "scopes": {"unit3": {"route": "physics", "topics": ["Gravity and motion"]}, "ea": {"route": "physics", "topics": ["Circular motion and gravitation"]}}, "question": "An object moves at constant speed in a circle.\nMass m = 0.50 kg\nSpeed v = 4.0 m s⁻¹\nRadius r = 2.0 m\n\n(a) Calculate its centripetal acceleration. (1 mark)\n\n(b) Calculate the net force. (1 mark)\n\n(c) State the direction of the acceleration and net force. (1 mark)", "answer": ["a=v²/r=16/2=8.0 m s⁻². F=ma=0.50×8.0=4.0 N. Both point towards the centre of the circle; velocity is tangential."], "points": [{"text": "Correct acceleration", "marks": 1}, {"text": "Correct force", "marks": 1}, {"text": "Correct inward direction", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_physics_25_syll.pdf"}, {"label": "Concept reference", "url": "https://openstax.org/books/university-physics-volume-1/pages/6-3-centripetal-force"}], "working": [{"heading": "List the quantities", "lines": ["m = 0.50 kg", "v = 4.0 m s⁻¹", "r = 2.0 m"]}, {"heading": "Centripetal acceleration", "lines": ["a = v²/r", "= (4.0)²/2.0", "= 8.0 m s⁻² towards the centre"]}, {"heading": "Net force", "lines": ["F = ma", "= 0.50 × 8.0", "= 4.0 N towards the centre"]}], "answerLayout": "steps", "partMarks": [1, 1, 1]}, {"id": "physics-magnetic", "template": "magnetic", "subject": "physics", "title": "Magnetic force on a charge", "scopes": {"unit3": {"route": "physics", "topics": ["Electromagnetism"]}, "ea": {"route": "physics", "topics": ["Magnetic fields and forces"]}}, "question": "A positive charge moves perpendicular to a uniform magnetic field.\nCharge q = 2.0 × 10⁻⁶ C\nSpeed v = 3.0 × 10⁴ m s⁻¹\nField B = 0.20 T\n\n(a) Calculate the magnetic-force magnitude. Show working. (2 marks)\n\n(b) State the force magnitude if the charge travels parallel to the field. (1 mark)", "answer": ["F=qvB sinθ=(2.0×10⁻⁶)(3.0×10⁴)(0.20)=0.012 N. For parallel motion θ=0°, so the magnetic force is zero."], "points": [{"text": "Correct perpendicular-force formula", "marks": 1}, {"text": "Correct 0.012 N", "marks": 1}, {"text": "Correct zero force for parallel motion", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_physics_25_syll.pdf"}, {"label": "Concept reference", "url": "https://openstax.org/books/university-physics-volume-2/pages/11-3-motion-of-a-charged-particle-in-a-magnetic-field"}], "working": [{"heading": "List the quantities", "lines": ["q = 2.0 × 10⁻⁶ C", "v = 3.0 × 10⁴ m s⁻¹", "B = 0.20 T", "θ = 90°"]}, {"heading": "Calculate the magnitude", "lines": ["F = qvB sinθ", "= (2.0 × 10⁻⁶)(3.0 × 10⁴)(0.20)sin90°", "= 0.012 N"]}, {"heading": "Parallel motion", "lines": ["θ = 0°, so sinθ = 0", "F = 0 N"]}], "answerLayout": "steps", "partMarks": [2, 1]}, {"id": "physics-photoelectric", "template": "photoelectric", "subject": "physics", "title": "Photon energy and emission", "scopes": {"ea": {"route": "physics", "topics": ["Photoelectric effect"]}}, "question": "Light strikes a metal surface.\nFrequency f = 8.0 × 10¹⁴ Hz\nWork function φ = 3.0 × 10⁻¹⁹ J\nPlanck constant h = 6.63 × 10⁻³⁴ J s\n\n(a) Calculate the maximum kinetic energy of an emitted electron. (2 marks)\n\n(b) Explain the effect of doubling intensity while frequency stays unchanged. (2 marks)", "answer": ["Photon energy=hf=5.304×10⁻¹⁹ J. Kmax=hf−φ=2.304×10⁻¹⁹ J≈2.3×10⁻¹⁹ J. With frequency unchanged, Kmax is unchanged. Doubling intensity supplies more photons per second and can increase emitted electrons per second under the same suitable conditions."], "points": [{"text": "Correct photon energy", "marks": 1}, {"text": "Correct Kmax", "marks": 1}, {"text": "Unchanged Kmax and increased photon flux explained", "marks": 2}], "marks": 4, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_physics_25_syll.pdf"}, {"label": "Concept reference", "url": "https://openstax.org/books/university-physics-volume-3/pages/6-2-photoelectric-effect"}], "working": [{"heading": "Photon energy", "lines": ["E = hf", "= (6.63 × 10⁻³⁴)(8.0 × 10¹⁴)", "= 5.304 × 10⁻¹⁹ J"]}, {"heading": "Maximum kinetic energy", "lines": ["Kmax = hf − φ", "= (5.304 − 3.0) × 10⁻¹⁹", "= 2.304 × 10⁻¹⁹ J", "Kmax ≈ 2.3 × 10⁻¹⁹ J"]}, {"heading": "Effect of greater intensity", "lines": ["The frequency and photon energy stay unchanged, so Kmax is unchanged.", "More photons arrive each second, potentially increasing emitted electrons per second under suitable conditions."]}], "answerLayout": "steps", "partMarks": [2, 2]}, {"id": "earth_science-ore", "template": "ore", "subject": "earth_science", "title": "Resource yield", "scopes": {"unit3": {"route": "earth_science", "topics": ["Use of non-renewable Earth resources"]}, "ea": {"route": "earth_science", "topics": ["Non-renewable resource formation and extraction", "Resource use and sustainability"]}}, "question": "An ore body has:\nore mass = 50,000 tonnes\nmetal grade = 2.0% by mass\nprocessing recovery = 80% of contained metal.\n\n(a) Calculate the contained metal and recovered metal. (2 marks)\n\n(b) Identify one factor other than grade that affects mining viability. (1 mark)", "answer": ["Contained metal=50,000×0.02=1,000 tonnes. Recovered metal=1,000×0.80=800 tonnes. Viability also depends on factors such as extraction/processing costs, market price, access, environmental management and approvals."], "points": [{"text": "Correct contained metal", "marks": 1}, {"text": "Correct recovered metal", "marks": 1}, {"text": "Relevant additional viability factor", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_earth_science_25_syll.pdf"}], "working": [{"heading": "Contained metal", "lines": ["Metal mass = ore mass × grade", "= 50,000 × 0.020", "= 1,000 tonnes"]}, {"heading": "Recovered metal", "lines": ["Recovered mass = contained metal × recovery fraction", "= 1,000 × 0.80", "= 800 tonnes"]}, {"heading": "Viability", "lines": ["Grade alone is insufficient. Costs, price, access, environmental management and approvals also matter."]}], "answerLayout": "steps", "partMarks": [2, 1]}, {"id": "earth_science-water", "template": "water", "subject": "earth_science", "title": "A renewable resource can decline", "scopes": {"unit3": {"route": "earth_science", "topics": ["Use of renewable Earth resources"]}, "ea": {"route": "earth_science", "topics": ["Soil and water resource management"]}}, "question": "Annual aquifer flows are:\nrecharge = 12 GL\nnatural discharge = 3 GL\npumping = 11 GL\n\nAssume these are the only flows.\n\n(a) Calculate annual storage change. Show working. (2 marks)\n\n(b) Propose a response and state one limitation of the simplified model. (1 mark)", "answer": ["Storage change=12−3−11=−2 GL per year. Under the simplified unchanged-flow model, pumping of at most 9 GL per year would avoid net storage decline. Monitoring, ecosystem needs and changing recharge must also inform a real allocation; this arithmetic is not a sustainable-yield assessment."], "points": [{"text": "Correct water balance", "marks": 1}, {"text": "Correct −2 GL decline", "marks": 1}, {"text": "Response linked to flows with a real-world limitation", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_earth_science_25_syll.pdf"}, {"label": "Concept reference", "url": "https://www.ga.gov.au/scientific-topics/water/groundwater/what-is-groundwater"}], "working": [{"heading": "Water balance", "lines": ["Storage change = recharge − natural discharge − pumping", "= 12 − 3 − 11", "= −2 GL per year"]}, {"heading": "Apply the simplified model", "lines": ["Pumping for zero net change = 12 − 3 = 9 GL per year"]}, {"heading": "Qualify the response", "lines": ["Real allocations also need monitoring, ecosystem requirements and changing recharge.", "A zero annual balance alone is not a sustainable-yield assessment."]}], "answerLayout": "steps", "partMarks": [2, 1]}, {"id": "earth_science-climate-data", "template": "climate-data", "subject": "earth_science", "title": "Weather and a trend", "scopes": {"ea": {"route": "earth_science", "topics": ["Climate models and Australian climate patterns"]}}, "question": "Synthetic 30-year mean temperatures for three consecutive non-overlapping periods are 18.0°C, 18.4°C and 18.9°C. Describe the change and explain why one unusually cold day would not refute it.", "answer": ["The mean increases by 0.9°C from the first to third period, with a 0.4°C increase then a 0.5°C increase. Climate concerns long-term patterns; one cold day is short-term weather variability and does not negate a long-term increase. These means alone do not identify a cause."], "points": [{"text": "Quantifies the 0.9°C increase", "marks": 1}, {"text": "Distinguishes weather from climate timescale", "marks": 1}, {"text": "Avoids attributing cause from these data alone", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_earth_science_25_syll.pdf"}], "working": [{"heading": "Quantify the change", "lines": ["First to second mean: 18.4 − 18.0 = 0.4°C", "Second to third mean: 18.9 − 18.4 = 0.5°C", "Overall: 18.9 − 18.0 = 0.9°C increase"]}, {"heading": "Interpret the timescale", "lines": ["Climate concerns long-term patterns.", "One cold day is short-term weather variability and does not refute a long-term increase.", "These means alone do not establish the cause."]}], "answerLayout": "steps"}, {"id": "marine_science-bleaching", "template": "bleaching", "subject": "marine_science", "title": "Interpret reef observations", "scopes": {"unit3": {"route": "marine_science", "topics": ["The reef and beyond", "Changes on the reef"]}, "ea": {"route": "marine_science", "topics": ["Coral reefs and ecosystem relationships", "Coral bleaching and resilience"]}}, "question": "Refer to the reef observations.\n\n(a) Calculate the difference in bleaching between the two groups in percentage points. (1 mark)\n\n(b) Explain how heat stress can affect the coral–algae relationship. (2 marks)\n\n(c) State one limitation on the conclusion supported by these data. (1 mark)", "answer": ["Bleaching is 60 percentage points higher at 31°C (70% versus 10%). Many shallow-water reef-building corals have symbiotic algae that supply photosynthetic products. Heat stress can disrupt this relationship and cause loss of algae/pigments, producing bleaching. Two groups without replication or full control of other variables cannot establish temperature as the sole cause. Bleached coral is not necessarily already dead."], "points": [{"text": "Correct percentage-point comparison", "marks": 1}, {"text": "Explains symbiosis and heat-stress disruption", "marks": 2}, {"text": "Relevant inference limitation", "marks": 1}], "marks": 4, "stimulus": "", "table": {"headers": ["Water temperature", "Colonies showing bleaching"], "rows": [["28°C", "10%"], ["31°C", "70%"]]}, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_marine_science_25_syll.pdf"}, {"label": "Concept reference", "url": "https://www.aims.gov.au/research-topics/environmental-issues/coral-bleaching/what-coral-bleaching"}], "working": [{"heading": "Compare the data", "lines": ["Difference = 70% − 10%", "= 60 percentage points higher at 31°C"]}, {"heading": "Explain the relationship", "lines": ["Many shallow-water reef-building corals contain symbiotic algae.", "The algae supply photosynthetic products.", "Heat stress can disrupt the relationship and cause loss of algae/pigments, producing bleaching."]}, {"heading": "Limit the inference", "lines": ["Two groups without replication or full control cannot establish temperature as the sole cause.", "Bleached coral is not necessarily already dead."]}], "answerLayout": "steps", "partMarks": [1, 2, 1]}, {"id": "marine_science-fish", "template": "fish", "subject": "marine_science", "title": "A mark–recapture estimate", "scopes": {"ea": {"route": "marine_science", "topics": ["Fishery sampling and population estimates"]}}, "question": "A mark–recapture study records:\nM = 80 initially marked fish\nC = 100 fish in the second sample\nR = 20 marked fish recaptured.\n\n(a) Estimate population size using N ≈ MC/R. (2 marks)\n\n(b) State two assumptions of the estimate. (2 marks)", "answer": ["N≈80×100/20=400 fish. Assumptions include a closed population during sampling, marks retained and recognised, enough mixing, and similar capture probability for marked and unmarked fish. Any two correctly explained assumptions are acceptable."], "points": [{"text": "Correct substitution and estimate", "marks": 2}, {"text": "Two relevant assumptions", "marks": 2}], "marks": 4, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_marine_science_25_syll.pdf"}], "working": [{"heading": "Identify the quantities", "lines": ["M = 80 initially marked fish", "C = 100 fish in the second sample", "R = 20 marked fish recaptured"]}, {"heading": "Estimate population size", "lines": ["N ≈ MC/R", "= (80 × 100)/20", "= 400 fish"]}, {"heading": "State assumptions", "lines": ["The population remains closed during sampling.", "Marks are retained/recognised and fish mix adequately.", "Marked and unmarked fish have similar capture probabilities.", "Any two relevant, explained assumptions can earn the indicated marks."]}], "answerLayout": "steps", "partMarks": [2, 2]}, {"id": "psychology-memory", "template": "memory", "subject": "psychology", "title": "Compare recall results", "scopes": {"unit3": {"route": "psychology", "topics": ["Memory"]}, "ea": {"route": "psychology", "topics": ["Models of memory"]}}, "question": "Refer to the recall data.\n\n(a) Calculate mean recall in each condition. (2 marks)\n\n(b) Calculate the mean difference. (1 mark)\n\n(c) Explain one limitation on generalising the results to all students. (1 mark)", "answer": ["Condition A mean=(6+8+7+9)/4=7.5 words. B mean=(10+11+9+10)/4=10 words. Difference=2.5 words in favour of B. Four results per condition are a small sample; representativeness and allocation/control of participant differences affect generalisation and causal inference."], "points": [{"text": "Correct two means", "marks": 2}, {"text": "Correct 2.5-word difference", "marks": 1}, {"text": "Relevant sample/design limitation", "marks": 1}], "marks": 4, "stimulus": "", "table": {"headers": ["Participant position", "A: words recalled", "B: words recalled"], "rows": [[1, 6, 10], [2, 8, 11], [3, 7, 9], [4, 9, 10]]}, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_psychology_25_syll.pdf"}], "working": [{"heading": "Condition A", "lines": ["Mean = (6 + 8 + 7 + 9)/4", "= 30/4", "= 7.5 words"]}, {"heading": "Condition B", "lines": ["Mean = (10 + 11 + 9 + 10)/4", "= 40/4", "= 10 words"]}, {"heading": "Mean difference", "lines": ["10 − 7.5 = 2.5 words in favour of B"]}, {"heading": "Limit the inference", "lines": ["Four results per condition are a small sample.", "Representativeness and allocation/control of participant differences affect generalisation and causal inference."]}], "answerLayout": "steps", "partMarks": [2, 1, 1]}, {"id": "psychology-conditioning", "template": "conditioning", "subject": "psychology", "title": "Identify classical conditioning", "scopes": {"unit3": {"route": "psychology", "topics": ["Learning"]}, "ea": {"route": "psychology", "topics": ["Classical and operant conditioning"]}}, "question": "A neutral tone is repeatedly followed by food, which naturally makes a dog salivate. Later the tone alone makes it salivate. Identify the unconditioned stimulus and response, and the conditioned stimulus and response.", "answer": ["Unconditioned stimulus: food. Unconditioned response: salivation to food. Conditioned stimulus: the tone after pairing. Conditioned response: salivation to the tone. The same response behaviour has a different eliciting stimulus."], "points": [{"text": "Correct unconditioned stimulus and response", "marks": 2}, {"text": "Correct conditioned stimulus and response", "marks": 2}], "marks": 4, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_psychology_25_syll.pdf"}, {"label": "Concept reference", "url": "https://openstax.org/books/psychology-2e/pages/6-2-classical-conditioning"}], "working": [{"heading": "Unconditioned pair", "lines": ["Unconditioned stimulus: food", "Unconditioned response: salivation to food"]}, {"heading": "Conditioned pair", "lines": ["Conditioned stimulus: tone after pairing with food", "Conditioned response: salivation to the tone"]}, {"heading": "Distinguish the responses", "lines": ["The behaviour is salivation in both cases, but the eliciting stimulus differs."]}], "answerLayout": "steps"}, {"id": "psychology-conformity", "template": "conformity", "subject": "psychology", "title": "Normative influence", "scopes": {"ea": {"route": "psychology", "topics": ["Social influence and conformity"]}}, "question": "A student privately disagrees with a group’s answer but publicly repeats it to avoid rejection. Identify the type of social influence and distinguish it from informational influence.", "answer": ["This is normative social influence: public agreement is driven by a wish for acceptance or avoidance of rejection. Informational influence involves treating others’ responses as evidence about what is correct, particularly under uncertainty. Here the student still privately disagrees."], "points": [{"text": "Correct normative influence", "marks": 1}, {"text": "Uses private disagreement/avoidance of rejection", "marks": 1}, {"text": "Correct contrast with informational influence", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_psychology_25_syll.pdf"}, {"label": "Concept reference", "url": "https://openstax.org/books/psychology-2e/pages/12-4-conformity-compliance-and-obedience"}], "working": [{"heading": "Identify the influence", "lines": ["Normative social influence"]}, {"heading": "Apply the evidence", "lines": ["The student agrees publicly to avoid rejection, while privately disagreeing."]}, {"heading": "Distinguish informational influence", "lines": ["Informational influence involves accepting others’ responses as evidence about what is correct, particularly when uncertain."]}], "answerLayout": "steps"}, {"id": "agricultural_science-feed", "template": "feed", "subject": "agricultural_science", "title": "Compare feed conversion", "scopes": {"unit3": {"route": "agricultural_science", "topics": ["Animal production B"]}, "ea": {"route": "agricultural_science", "topics": ["Animal nutrition and digestion"]}}, "question": "Group A consumes 200 kg of feed and gains 40 kg. Group B consumes 225 kg and gains 50 kg.\n\n(a) Calculate FCR for each group using feed consumed / live-mass gain. (2 marks)\n\n(b) Identify the more feed-efficient group. (1 mark)\n\n(c) State one additional consideration when comparing the groups. (1 mark)", "answer": ["A:200/40=5.0 kg feed per kg gain. B:225/50=4.5 kg feed per kg gain. B uses less feed per unit gain. Feed cost, animal health/welfare and comparable age, conditions and feed composition should also be considered; FCR alone does not establish overall profitability."], "points": [{"text": "Correct two ratios", "marks": 2}, {"text": "Correct interpretation: B", "marks": 1}, {"text": "Relevant additional consideration", "marks": 1}], "marks": 4, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_agricultural_science_25_syll.pdf"}], "working": [{"heading": "Formula", "lines": ["FCR = feed consumed / live-mass gain"]}, {"heading": "Calculate each ratio", "lines": ["Group A: 200/40 = 5.0 kg feed per kg gain", "Group B: 225/50 = 4.5 kg feed per kg gain"]}, {"heading": "Interpret", "lines": ["B is more feed-efficient because it uses less feed per kilogram gained."]}, {"heading": "Qualify the comparison", "lines": ["Consider feed costs, welfare, health and comparable conditions.", "FCR alone does not establish overall profitability."]}], "answerLayout": "steps", "partMarks": [2, 1, 1]}, {"id": "agricultural_science-plants", "template": "plants", "subject": "agricultural_science", "title": "Compare trial yields", "scopes": {"unit3": {"route": "agricultural_science", "topics": ["Plant production B"]}, "ea": {"route": "agricultural_science", "topics": ["Plant agronomy and nutrient management"]}}, "question": "Refer to the crop trial data.\n\n(a) Calculate the percentage increase from control to treatment. (2 marks)\n\n(b) Propose one design improvement and explain why it matters. (2 marks)", "answer": ["Increase=(6.0−5.0)/5.0×100=20%. Randomised replicated plots would help separate treatment effects from location or chance variation; control other relevant inputs. A single plot per condition gives weak evidence for a general recommendation."], "points": [{"text": "Correct baseline and calculation", "marks": 2}, {"text": "Suitable design improvement", "marks": 1}, {"text": "Explains its value", "marks": 1}], "marks": 4, "stimulus": "", "table": {"headers": ["Treatment", "Yield (t ha⁻¹)"], "rows": [["Control", 5.0], ["Treatment", 6.0]]}, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_agricultural_science_25_syll.pdf"}], "working": [{"heading": "Percentage increase", "lines": ["Increase = [(treatment − control)/control] × 100", "= [(6.0 − 5.0)/5.0] × 100", "= 20%"]}, {"heading": "Improve the design", "lines": ["Use randomised, replicated plots and control other inputs."]}, {"heading": "Explain why", "lines": ["This helps separate treatment effects from location and chance variation.", "One plot per condition gives weak evidence for a general recommendation."]}], "answerLayout": "steps", "partMarks": [2, 2]}, {"id": "agricultural_science-enterprise", "template": "enterprise", "subject": "agricultural_science", "title": "A gross margin", "scopes": {"unit3": {"route": "agricultural_science", "topics": ["Agricultural enterprises B"]}, "ea": {"route": "agricultural_science", "topics": ["Enterprise records and financial management"]}}, "question": "A crop enterprise records:\nrevenue = $72,000\nvariable costs = $45,000.\n\n(a) Calculate gross margin. (1 mark)\n\n(b) Explain why gross margin is not necessarily net profit. (2 marks)", "answer": ["Gross margin=$72,000−$45,000=$27,000. It excludes fixed/overhead costs, so those and other relevant costs must be considered to determine net profit."], "points": [{"text": "Correct gross margin", "marks": 1}, {"text": "Identifies excluded fixed/overhead costs", "marks": 1}, {"text": "Links exclusion to net-profit distinction", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_agricultural_science_25_syll.pdf"}], "working": [{"heading": "Formula", "lines": ["Gross margin = revenue − variable costs"]}, {"heading": "Substitute and calculate", "lines": ["= $72,000 − $45,000", "= $27,000"]}, {"heading": "Distinguish net profit", "lines": ["Gross margin excludes fixed/overhead costs.", "Those and other relevant costs must be considered to determine net profit."]}], "answerLayout": "steps", "partMarks": [1, 2]}, {"id": "engineering-beam", "template": "beam", "subject": "engineering", "title": "A simply supported beam", "scopes": {"unit3": {"route": "engineering", "topics": ["Forces, loading and structural analysis"]}}, "question": "A 6.0 m horizontal beam is simply supported at each end. A 12 kN downward point load acts 2.0 m from the left support. Ignore beam weight. Calculate the vertical reactions.", "answer": ["Taking moments about the left support: Rright×6=12×2, so Rright=4 kN upward. Vertical equilibrium gives Rleft+4=12, so Rleft=8 kN upward."], "points": [{"text": "Correct moment balance", "marks": 1}, {"text": "Correct right reaction", "marks": 1}, {"text": "Correct left reaction with direction", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_engineering_25_syll.pdf"}], "working": [{"heading": "Moment equilibrium about the left support", "lines": ["Rright × 6.0 = 12 × 2.0", "Rright = 24/6.0 = 4 kN upward"]}, {"heading": "Vertical force equilibrium", "lines": ["Rleft + Rright − 12 = 0", "Rleft = 12 − 4 = 8 kN upward"]}], "answerLayout": "steps"}, {"id": "engineering-stress", "template": "stress", "subject": "engineering", "title": "Axial stress", "scopes": {"unit3": {"route": "engineering", "topics": ["Civil engineering materials", "Engineering solutions: synthesis, evaluation and refinement"]}}, "question": "An axial tensile force of 20 kN acts on a member with cross-sectional area 100 mm². Calculate tensile stress in MPa. A specified allowable stress is 150 MPa. Does this meet that criterion?", "answer": ["Stress=F/A=20,000/100=200 N mm⁻²=200 MPa. It exceeds 150 MPa, so it does not meet this allowable-stress criterion. This calculation alone is not a complete structural design check."], "points": [{"text": "Correct force/area conversion", "marks": 1}, {"text": "Correct 200 MPa", "marks": 1}, {"text": "Correct comparison and conclusion", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_engineering_25_syll.pdf"}], "working": [{"heading": "Convert force", "lines": ["F = 20 kN = 20,000 N", "A = 100 mm²"]}, {"heading": "Calculate stress", "lines": ["σ = F/A", "= 20,000/100", "= 200 N mm⁻² = 200 MPa"]}, {"heading": "Compare with the criterion", "lines": ["200 MPa > 150 MPa", "The member does not meet the given allowable-stress criterion.", "This is not a complete structural design check."]}], "answerLayout": "steps"}, {"id": "engineering-power", "template": "power", "subject": "engineering", "title": "Efficiency and power", "scopes": {"ea": {"route": "engineering", "topics": ["Mechanical power and efficiency"]}}, "question": "A motor supplies 800 W to a mechanism whose useful output is 600 W. Calculate efficiency and wasted power. If useful output must be 900 W at the same efficiency, what input is needed?", "answer": ["Efficiency=600/800=0.75=75%. Wasted power=200 W. Required input=900/0.75=1,200 W."], "points": [{"text": "Correct efficiency", "marks": 1}, {"text": "Correct loss", "marks": 1}, {"text": "Correct required input", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_engineering_25_syll.pdf"}], "working": [{"heading": "Efficiency", "lines": ["η = useful output / input", "= 600/800 = 0.75 = 75%"]}, {"heading": "Wasted power", "lines": ["800 − 600 = 200 W"]}, {"heading": "Required input", "lines": ["Input = useful output / η", "= 900/0.75", "= 1,200 W"]}], "answerLayout": "steps"}, {"id": "engineering-gears", "template": "gears", "subject": "engineering", "title": "Gear ratio", "scopes": {"ea": {"route": "engineering", "topics": ["Belts and gears"]}}, "question": "A 20-tooth driver rotates at 1,200 rpm and meshes directly with a 60-tooth driven gear. Calculate driven speed and describe direction. Ignore losses.", "answer": ["Driven speed=1,200×20/60=400 rpm. Directly meshing external gears turn in opposite directions. The ideal output torque is three times the input torque."], "points": [{"text": "Correct ratio/method", "marks": 1}, {"text": "Correct 400 rpm", "marks": 1}, {"text": "Correct opposite direction", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_engineering_25_syll.pdf"}], "working": [{"heading": "Speed ratio", "lines": ["Driven speed = driver speed × driver teeth / driven teeth", "= 1,200 × 20/60", "= 400 rpm"]}, {"heading": "Direction", "lines": ["Directly meshing external gears rotate in opposite directions."]}], "answerLayout": "steps"}, {"id": "aerospace_sys-turnaround", "template": "turnaround", "subject": "aerospace_sys", "title": "Find the operational bottleneck", "scopes": {"unit3": {"route": "aerospace_sys", "topics": ["Airport and airline operation systems", "Operational calculations and recommendations"]}}, "question": "After an aircraft arrives, refuelling takes 18 minutes and cabin servicing takes 25 minutes; both start together. Boarding takes 15 minutes and starts only when both finish. Calculate the earliest departure-ready time after arrival. Which improvement saves more time: reducing refuelling by 5 minutes or cabin servicing by 5 minutes?", "answer": ["Parallel tasks finish when the slower one finishes: 25 minutes. Add boarding:40 minutes. Refuelling reduction leaves 40 minutes unchanged. Cabin servicing reduction makes the parallel stage max(18,20)=20 minutes, giving 35 minutes total. Reducing cabin servicing saves 5 minutes under these assumptions."], "points": [{"text": "Correct baseline time", "marks": 1}, {"text": "Correct refuelling result", "marks": 1}, {"text": "Correct cabin result and recommendation", "marks": 2}], "marks": 4, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_aerospace_sys_25_syll.pdf"}], "working": [{"heading": "Baseline", "lines": ["Parallel stage = max(18, 25) = 25 minutes", "Total = 25 + 15 = 40 minutes"]}, {"heading": "Reduce refuelling by 5 minutes", "lines": ["Parallel stage = max(13, 25) = 25 minutes", "Total = 40 minutes: no saving"]}, {"heading": "Reduce cabin servicing by 5 minutes", "lines": ["Parallel stage = max(18, 20) = 20 minutes", "Total = 20 + 15 = 35 minutes", "Cabin-servicing reduction saves 5 minutes."]}], "answerLayout": "steps"}, {"id": "aerospace_sys-safety", "template": "safety", "subject": "aerospace_sys", "title": "Respond to a recurring incident", "scopes": {"unit3": {"route": "aerospace_sys", "topics": ["Aerospace safety and operational systems", "Operational accident and incident investigation"]}}, "question": "A fictional airport log records 12 vehicle incursions in a month; 9 involve unclear route markings at night. Recommend one preventive change and an evaluation measure. Explain a limitation of the evidence.", "answer": ["Improve route markings and lighting at the identified location, with appropriate staff briefing. Compare incursion rates per vehicle movement before and after implementation, especially at night. Counts alone do not control for traffic volume or other conditions; the log suggests a focus but does not prove markings caused every incident. Other justified prevention measures can earn credit."], "points": [{"text": "Specific response linked to evidence", "marks": 1}, {"text": "Suitable rate-based evaluation", "marks": 1}, {"text": "Evidence limitation explained", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_aerospace_sys_25_syll.pdf"}]}, {"id": "aerospace_sys-fuel", "template": "fuel", "subject": "aerospace_sys", "title": "A planning calculation", "scopes": {"ea": {"route": "aerospace_sys", "topics": ["Fuel planning and reserves"]}}, "question": "For a classroom calculation only: a flight takes 2.0 hours at 36 L h⁻¹. Add a separately specified 18 L reserve and 6 L taxi allowance. Calculate total fuel and compare with 100 L available. Do not infer regulatory fuel minima.", "answer": ["Trip fuel=2×36=72 L. Total under the supplied planning assumptions=72+18+6=96 L. 100 L exceeds that total by 4 L. Actual flight planning requires current operational and regulatory requirements; the supplied reserve is an exercise value."], "points": [{"text": "Correct trip fuel", "marks": 1}, {"text": "Correct total", "marks": 1}, {"text": "Correct 4 L comparison", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_aerospace_sys_25_syll.pdf"}], "working": [{"heading": "Trip fuel", "lines": ["Time × rate = 2.0 × 36 = 72 L"]}, {"heading": "Total under the exercise assumptions", "lines": ["Trip + reserve + taxi = 72 + 18 + 6 = 96 L"]}, {"heading": "Compare with available fuel", "lines": ["100 − 96 = 4 L above the exercise total", "The supplied reserve is an exercise value, not a regulatory minimum."]}], "answerLayout": "steps"}, {"id": "aerospace_sys-navigation", "template": "navigation", "subject": "aerospace_sys", "title": "Time and ground speed", "scopes": {"ea": {"route": "aerospace_sys", "topics": ["Aeronautical charts and navigation"]}}, "question": "An aircraft covers a 180 nautical mile leg at a ground speed of 120 knots. Calculate travel time. If ground speed falls to 100 knots, how much longer does it take?", "answer": ["At 120 knots:180/120=1.5 hours=90 minutes. At 100 knots:1.8 hours=108 minutes. Difference=18 minutes. Use ground speed for ground distance, rather than substituting airspeed without wind correction."], "points": [{"text": "Correct first time", "marks": 1}, {"text": "Correct second time", "marks": 1}, {"text": "Correct difference", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_aerospace_sys_25_syll.pdf"}], "working": [{"heading": "At 120 knots", "lines": ["Time = distance / ground speed", "= 180/120 = 1.5 hours", "= 90 minutes"]}, {"heading": "At 100 knots", "lines": ["Time = 180/100 = 1.8 hours", "= 108 minutes"]}, {"heading": "Difference", "lines": ["108 − 90 = 18 minutes longer"]}], "answerLayout": "steps"}, {"id": "food-starch", "template": "starch", "subject": "food", "title": "Interpret a thickening trial", "scopes": {"unit3": {"route": "food", "topics": ["Carbohydrate: nutritional, chemical and functional properties", "Food problem constraints and success criteria", "Synthesising, evaluating and refining food solutions"]}}, "question": "Use the synthetic results. Identify the trend and recommend a tested concentration if the success criterion is a spread diameter of at most 60 mm. Explain one limitation.", "answer": ["Spread diameter decreases as starch concentration increases, consistent with a thicker paste under the test conditions. Both 6% and 8% meet the ≤60 mm criterion. A defensible choice is 6% if minimising starch/cost is an additional aim. Repeats, consistent heating and sensory testing are needed; the table alone does not establish acceptability."], "points": [{"text": "Correct trend using evidence", "marks": 1}, {"text": "Identifies both qualifying concentrations", "marks": 1}, {"text": "Justifies a choice and limitation", "marks": 2}], "marks": 4, "stimulus": "", "table": {"headers": ["Starch concentration", "Spread diameter"], "rows": [["4%", "80 mm"], ["6%", "55 mm"], ["8%", "40 mm"]]}, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_food_25_syll.pdf"}]}, {"id": "food-fat", "template": "fat", "subject": "food", "title": "Protect a fat-rich product", "scopes": {"unit3": {"route": "food", "topics": ["Fat: nutritional, chemical and functional properties", "Fat processing, preservation and spoilage"]}}, "question": "A fat-rich snack develops an undesirable rancid smell faster in warm, transparent packaging than in cool, opaque packaging. Explain a plausible mechanism and propose a controlled test of packaging opacity.", "answer": ["Oxidative rancidity is a plausible mechanism: light, oxygen and temperature can influence lipid oxidation. To test opacity, compare otherwise identical opaque and transparent packs at the same temperature, oxygen exposure and storage time, using replicates and a suitable rancidity measure. The initial comparison changes both light and temperature, so it cannot isolate opacity."], "points": [{"text": "Plausible lipid-oxidation explanation", "marks": 1}, {"text": "Controls temperature and other relevant variables", "marks": 1}, {"text": "Replicates/measurement specified", "marks": 1}, {"text": "Recognises original confounding", "marks": 1}], "marks": 4, "stimulus": "", "table": null, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_food_25_syll.pdf"}]}, {"id": "food-allergy", "template": "allergy", "subject": "food", "title": "Evaluate a consumer formulation", "scopes": {"ea": {"route": "food", "topics": ["Food allergy and intolerance markets", "Food formulation for consumer needs"]}}, "question": "A school specifies a milk-free snack for consumers with milk allergy. The proposed recipe replaces milk with lactose-free cow’s milk. Does this satisfy the criterion? Explain and suggest a better next step.", "answer": ["No. Lactose-free cow’s milk can still contain milk proteins that trigger milk allergy. Lactose intolerance and milk allergy are different. Select ingredients that meet the milk-free specification, check allergen declarations and manage cross-contact; verify the complete formulation against the consumer brief."], "points": [{"text": "Correct rejection", "marks": 1}, {"text": "Explains milk protein versus lactose distinction", "marks": 1}, {"text": "Suitable ingredient/allergen-control next step", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_food_25_syll.pdf"}, {"label": "Concept reference", "url": "https://www.foodauthority.nsw.gov.au/consumer/food-allergies/food-allergens/milk"}, {"label": "Concept reference", "url": "https://www.foodstandards.gov.au/consumer/labelling/allergen-labelling"}]}, {"id": "geography-cover", "template": "cover", "subject": "geography", "title": "Quantify land-cover change", "scopes": {"unit3": {"route": "geography", "topics": ["Land cover transformations: processes, patterns and causes", "Land cover, Earth systems and climate change", "Analysing geographical relationships and impacts"]}}, "question": "A 1,000 km² catchment has 60% forest cover in Year 1 and 45% in Year 2.\n\n(a) Calculate the area of forest lost. (1 mark)\n\n(b) Calculate the percentage-point change and the percentage decrease relative to Year 1. (2 marks)\n\n(c) Explain one possible consequence of this land-cover change. (1 mark)", "answer": ["Forest area falls from 600 to 450 km²:150 km² lost. Change=−15 percentage points. Relative decrease=150/600×100=25%. Removing forest can reduce interception and increase runoff/erosion under otherwise similar conditions; the actual effect depends on replacement cover, rainfall and management."], "points": [{"text": "Correct lost area", "marks": 1}, {"text": "Correct percentage-point change", "marks": 1}, {"text": "Correct relative decrease", "marks": 1}, {"text": "Plausible qualified consequence", "marks": 1}], "marks": 4, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_geography_25_syll.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_geography_25_ia1_smple_ass_inst.pdf"}], "partMarks": [1, 2, 1], "working": [{"heading": "Forest area", "lines": ["Year 1 = 0.60 × 1,000 = 600 km²", "Year 2 = 0.45 × 1,000 = 450 km²", "Area lost = 600 − 450 = 150 km²"]}, {"heading": "Two different percentage measures", "lines": ["Percentage-point change = 45 − 60 = −15 percentage points", "Relative decrease = (150/600) × 100 = 25%"]}, {"heading": "Consequence", "lines": ["Less forest can reduce interception and increase runoff or erosion.", "Actual effects depend on replacement cover, rainfall and management."]}], "answerLayout": "steps"}, {"id": "geography-spatial", "template": "spatial", "subject": "geography", "title": "Target a geographical response", "scopes": {"unit3": {"route": "geography", "topics": ["Reading maps, graphs and spatial data", "Analysing geographical relationships and impacts", "Proposing and justifying responses to a geographical challenge"]}}, "question": "Refer to the subcatchment data.\n\n(a) Identify a priority subcatchment for an erosion-control investigation. (1 mark)\n\n(b) Justify your choice using two variables from the table. (2 marks)\n\n(c) Identify one additional dataset needed to assess erosion risk. (1 mark)", "answer": ["B is a defensible priority: it has the lowest vegetation cover (20%) and steepest mean slope (18°), both relevant to runoff/erosion risk. Rainfall intensity, soil erodibility, land management or measured sediment yield would strengthen the assessment. These three variables alone do not prove actual erosion rates."], "points": [{"text": "Clear priority", "marks": 1}, {"text": "Uses both relevant variables accurately", "marks": 2}, {"text": "Relevant additional dataset and purpose", "marks": 1}], "marks": 4, "stimulus": "", "table": {"headers": ["Subcatchment", "Vegetation cover", "Mean slope"], "rows": [["A", "70%", "5°"], ["B", "20%", "18°"], ["C", "45%", "8°"]]}, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_geography_25_syll.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_geography_25_ia1_smple_ass_inst.pdf"}], "partMarks": [1, 2, 1]}, {"id": "geography-population", "template": "population", "subject": "geography", "title": "Calculate population change", "scopes": {"ea": {"route": "geography", "topics": ["Global population growth and distribution", "Internal and international migration"]}}, "question": "A city has 200,000 people at the start of a year. It records 3,000 births, 1,800 deaths, 5,000 arrivals and 3,200 departures.\n\n(a) Calculate natural increase. (1 mark)\n\n(b) Calculate net migration. (1 mark)\n\n(c) Calculate the population at the end of the year. (1 mark)", "answer": ["Natural increase=3,000−1,800=1,200. Net migration=5,000−3,200=1,800. Total increase=3,000. Final population=203,000, assuming no other adjustments."], "points": [{"text": "Correct natural increase", "marks": 1}, {"text": "Correct net migration", "marks": 1}, {"text": "Correct final population", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_geography_25_syll.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_geography_25_ia1_smple_ass_inst.pdf"}], "partMarks": [1, 1, 1], "working": [{"heading": "Natural increase", "lines": ["Births − deaths = 3,000 − 1,800 = 1,200 people"]}, {"heading": "Net migration", "lines": ["Arrivals − departures = 5,000 − 3,200 = 1,800 people"]}, {"heading": "Final population", "lines": ["Total increase = 1,200 + 1,800 = 3,000 people", "Final population = 200,000 + 3,000 = 203,000 people"]}], "answerLayout": "steps"}, {"id": "geography-ageing", "template": "ageing", "subject": "geography", "title": "Interpret age structure", "scopes": {"ea": {"route": "geography", "topics": ["Population pyramids", "Population-change responses"]}}, "question": "A population has the following age shares:\n0–14 years: 15%\n15–64 years: 60%\n65 years and over: 25%.\n\n(a) Calculate and interpret the total age-dependency ratio. Use [(0–14)+(65+)]/(15–64) × 100. (2 marks)\n\n(b) Explain one planning implication and one limitation of this ratio. (2 marks)", "answer": ["Ratio=(15+25)/60×100≈66.7 age dependants per 100 people aged 15–64. The relatively large older share can inform planning for accessible transport, housing or health services. Age bands do not measure actual employment or financial dependence: some older people work and some working-age people do not."], "points": [{"text": "Correct ratio", "marks": 1}, {"text": "Correct units/interpretation", "marks": 1}, {"text": "Relevant implication", "marks": 1}, {"text": "Recognises demographic proxy limitation", "marks": 1}], "marks": 4, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_geography_25_syll.pdf"}, {"label": "Question-design reference (not QCAA endorsement of this practice item)", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/hass/snr_geography_25_ia1_smple_ass_inst.pdf"}], "partMarks": [2, 2], "working": [{"heading": "Formula", "lines": ["Ratio = [(0–14 share) + (65+ share)] / (15–64 share) × 100"]}, {"heading": "Substitute and calculate", "lines": ["= [(15 + 25)/60] × 100", "≈ 66.7 age dependants per 100 people aged 15–64"]}, {"heading": "Planning implication", "lines": ["The older age share can inform accessible transport, housing and health-service planning."]}, {"heading": "Limitation", "lines": ["Age bands do not establish actual employment or financial dependence."]}], "answerLayout": "steps"}, {"id": "digital_solutions-trace", "template": "trace", "subject": "digital_solutions", "title": "Trace a validation algorithm", "scopes": {"ea": {"route": "digital_solutions", "topics": ["Pseudocode and data-exchange algorithms", "Variables, validation and data integrity"]}}, "question": "Trace this algorithm for [4, −2, 7, 0]: total←0; FOR EACH n: IF n>0 THEN total←total+n; OUTPUT total. Give the output and a boundary test for n>0.", "answer": ["The positive values are 4 and 7, so total=11. A boundary test is input 0: it should not be added. Inputs just below and above the boundary, such as −1 and 1, help test the comparison."], "points": [{"text": "Correct output 11", "marks": 1}, {"text": "Correct boundary test and expected behaviour", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_digital_solutions_25_syll.pdf"}]}, {"id": "digital_solutions-sql", "template": "sql", "subject": "digital_solutions", "title": "Select the intended records", "scopes": {"ea": {"route": "digital_solutions", "topics": ["SQL and programmed data exchanges"]}}, "question": "Table Student(id, name, score) contains (1,Ana,72), (2,Ben,49), (3,Chen,85). Write SQL to return only name and score where score is at least 70, in descending score order. Give the result.", "answer": ["SELECT name, score FROM Student WHERE score >= 70 ORDER BY score DESC; Result: Chen,85 followed by Ana,72. Equivalent valid SQL earns credit."], "points": [{"text": "Correct columns and table", "marks": 1}, {"text": "Correct inclusive condition", "marks": 1}, {"text": "Correct descending order and result", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_digital_solutions_25_syll.pdf"}]}, {"id": "digital_solutions-hash", "template": "hash", "subject": "digital_solutions", "title": "Hashing and encryption", "scopes": {"ea": {"route": "digital_solutions", "topics": ["Encryption and authentication", "Hashing, checksums and compression"]}}, "question": "A developer says “We can decrypt a password hash when a user forgets their password.” Explain the error and describe an appropriate recovery approach.", "answer": ["A cryptographic hash is designed as a one-way mapping; it is not encryption with a decryption key. Password verification compares an appropriate password-hash result, using a suitable salted password-hashing scheme. Recovery should use a securely verified reset process rather than retrieving the original password."], "points": [{"text": "Correct one-way versus reversible distinction", "marks": 1}, {"text": "Correct verification concept", "marks": 1}, {"text": "Appropriate reset rather than recovery of plaintext", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_digital_solutions_25_syll.pdf"}]}, {"id": "pe-training", "template": "training", "subject": "pe", "title": "Apply specificity", "scopes": {"ea": {"route": "pe", "topics": ["ATP resynthesis and energy-system interplay", "Fitness components and activity demands", "Training principles", "Training methods"]}}, "question": "A player repeatedly sprints for 6 seconds with short recoveries during a match. A proposed program contains only one continuous 40-minute easy run each week. Evaluate specificity and propose one improvement.", "answer": ["The easy continuous run can contribute to aerobic fitness but does not closely reproduce repeated high-intensity sprint demands. Add appropriately planned repeated-sprint/interval work with sport-relevant movements and work–recovery periods, allowing recovery and progression. Energy systems contribute together; a 6-second sprint should not be described as using only one system."], "points": [{"text": "Compares program to match demands", "marks": 1}, {"text": "Specific suitable improvement", "marks": 1}, {"text": "Explains training/energy-system rationale", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_pe_25_syll.pdf"}]}, {"id": "essential_maths-estimate", "template": "estimate", "subject": "essential_maths", "title": "Shopping with a budget", "scopes": {"unit3": {"route": "essential_maths", "topics": ["Calculations and reasonable estimates"]}}, "question": "You have $30. You buy three items at $7.80 each and one item at $4.50. Find the total and the change.", "answer": ["Three items cost 3×$7.80=$23.40. Total=$23.40+$4.50=$27.90. Change=$30−$27.90=$2.10."], "points": [{"text": "Correct multiplication", "marks": 1}, {"text": "Correct total", "marks": 1}, {"text": "Correct change", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_ess_maths_25_app_syll.pdf"}], "working": [{"heading": "Cost of three items", "lines": ["3 × $7.80 = $23.40"]}, {"heading": "Total cost", "lines": ["$23.40 + $4.50 = $27.90"]}, {"heading": "Change", "lines": ["$30.00 − $27.90 = $2.10"]}], "answerLayout": "steps"}, {"id": "essential_maths-paint", "template": "paint", "subject": "essential_maths", "title": "Paint a wall", "scopes": {"unit3": {"route": "essential_maths", "topics": ["Measurement and unit conversions"]}}, "question": "A rectangular wall is 4.0 m wide and 2.5 m high. A window covers 2.0 m². One litre of paint covers 8 m² for one coat. How many litres are needed for one coat? Ignore wastage.", "answer": ["Wall area=4×2.5=10 m². Paint area=10−2=8 m². Paint needed=8÷8=1 litre."], "points": [{"text": "Correct wall area", "marks": 1}, {"text": "Subtracts window", "marks": 1}, {"text": "Correct paint amount", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_ess_maths_25_app_syll.pdf"}], "working": [{"heading": "Wall area", "lines": ["Area = width × height", "= 4.0 × 2.5", "= 10 m²"]}, {"heading": "Area to paint", "lines": ["10 − 2.0 = 8.0 m²"]}, {"heading": "Paint needed", "lines": ["Litres = area ÷ coverage", "= 8.0 ÷ 8", "= 1 litre for one coat"]}], "answerLayout": "steps"}, {"id": "essential_maths-scale", "template": "scale", "subject": "essential_maths", "title": "Read a plan", "scopes": {"unit3": {"route": "essential_maths", "topics": ["Scales, plans and models"]}}, "question": "A plan uses a scale of 1:100. A room is 45 mm long on the plan. What is the real length in metres?", "answer": ["Real length=45×100=4,500 mm. Divide by 1,000 to convert to metres:4.5 m."], "points": [{"text": "Correct scale multiplication", "marks": 1}, {"text": "Correct conversion to 4.5 m", "marks": 1}], "marks": 2, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_ess_maths_25_app_syll.pdf"}], "working": [{"heading": "Use the scale", "lines": ["Real length = plan length × 100", "= 45 × 100", "= 4,500 mm"]}, {"heading": "Convert to metres", "lines": ["4,500 ÷ 1,000 = 4.5 m"]}], "answerLayout": "steps"}, {"id": "essential_maths-chance", "template": "chance", "subject": "essential_maths", "title": "Use trial results", "scopes": {"unit3": {"route": "essential_maths", "topics": ["Probability and relative frequencies"]}}, "question": "A spinner lands on blue 18 times in 60 spins. Find the relative frequency of blue. Use this result to predict blue outcomes in another 200 spins. Is that prediction guaranteed?", "answer": ["Relative frequency=18/60=0.30 (30%). Prediction=0.30×200=60 blue outcomes. It is an estimate; random results can vary."], "points": [{"text": "Correct relative frequency", "marks": 1}, {"text": "Correct estimate", "marks": 1}, {"text": "Explains it is not guaranteed", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "easy", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_ess_maths_25_app_syll.pdf"}], "working": [{"heading": "Relative frequency", "lines": ["18 ÷ 60 = 0.30 = 30%"]}, {"heading": "Prediction", "lines": ["0.30 × 200 = 60 blue outcomes"]}, {"heading": "Explain", "lines": ["This is an estimate. Random results can vary, so 60 is not guaranteed."]}], "answerLayout": "steps"}, {"id": "essential_english-poster", "template": "poster", "subject": "essential_english", "title": "Explain a poster’s message", "scopes": {"unit3": {"route": "essential_english", "topics": ["How a text shows people, places, events, ideas or issues", "How words, pictures and layout create a message", "Using details from the text to explain your answer"]}}, "question": "Read the made-up poster below. Who is it for? What does it ask them to do? Explain how ONE choice of words helps the message.", "answer": ["It is for students at the school. It asks them to bring a refillable bottle on Friday. “Small change. Less waste.” makes the action sound manageable and links it to a benefit. “Join us” gives an inclusive invitation. Either choice can be explained with a detail from the poster."], "points": [{"text": "Identifies the student audience", "marks": 1}, {"text": "Explains the action requested", "marks": 1}, {"text": "Uses a specific wording detail and explains its effect", "marks": 2}], "marks": 4, "stimulus": "Original practice poster — general reading skills, not a released CIA topic or paper.\nSCHOOL REFILL FRIDAY\nBring your bottle this Friday.\nSmall change. Less waste.\nJoin us at the refill station near the library.", "table": null, "difficulty": "easy", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/senior/assessment/internal-assessment/common-internal-assessment/essential-english"}]}, {"id": "essential_english-compare", "template": "compare", "subject": "essential_english", "title": "Two ways to present an event", "scopes": {"unit3": {"route": "essential_english", "topics": ["How a text shows people, places, events, ideas or issues", "How words, pictures and layout create a message", "Using details from the text to explain your answer"]}}, "question": "Read the two made-up notices. How does each make the lunchtime reading club sound? Use a word or phrase from each to explain your answer.", "answer": ["A makes the club sound quiet and welcoming: “relax” and “read at your own pace” suggest no pressure. B makes it sound like a competition: “challenge” and “top the leaderboard” focus on winning or achievement. Both discuss reading, but they encourage students in different ways. Other supported explanations can earn credit."], "points": [{"text": "Explains A with a detail", "marks": 2}, {"text": "Explains B with a detail", "marks": 2}, {"text": "Makes a clear comparison", "marks": 1}], "marks": 5, "stimulus": "Original general skills practice, not a released CIA topic.\nNotice A: Need a quiet break? Relax with a book at lunchtime. Read at your own pace. Everyone is welcome.\nNotice B: Take the reading challenge! Finish five books and see if you can top the leaderboard.", "table": null, "difficulty": "easy", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/senior/assessment/internal-assessment/common-internal-assessment/essential-english"}]}, {"id": "ancient_history-source-purpose", "template": "source-purpose", "subject": "ancient_history", "title": "Purpose and usefulness", "scopes": {"ea": {"route": "ancient_history", "topics": ["Historical perspectives on {option}", "Source usefulness and reliability for {option}", "Corroborating evidence about {option}"]}}, "question": "Refer to the hypothetical source description.\n\n(a) Explain one use of the source for a historical inquiry. (1 mark)\n\n(b) Explain one limitation of the source. (1 mark)\n\n(c) Identify another source that could test its claim and explain its use. (1 mark)", "answer": ["It could show how the leader wanted an audience to understand the event and what image the regime promoted. Its persuasive public purpose means it may omit defeats or exaggerate support; it cannot alone establish unanimous approval. An independently produced contemporary account, material evidence or records of opponents could corroborate or challenge the claim. Usefulness depends on the inquiry, rather than a source being simply “good” or “bad”."], "points": [{"text": "Usefulness linked to purpose/perspective", "marks": 1}, {"text": "Limitation linked to the claim", "marks": 1}, {"text": "Suitable corroborating source and purpose", "marks": 1}], "marks": 3, "stimulus": "Hypothetical source-skills exercise, not an authentic historical quotation or evidence about your selected topic. A public statement commissioned by a ruler soon after a disputed event claims that everyone supported the ruler. It was displayed prominently for the ruler’s subjects to read.", "table": null, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_ancient_history_25_syll.pdf"}], "partMarks": [1, 1, 1]}, {"id": "ancient_history-corroboration", "template": "corroboration", "subject": "ancient_history", "title": "Agreement is not independence", "scopes": {"ea": {"route": "ancient_history", "topics": ["Source usefulness and reliability for {option}", "Corroborating evidence about {option}", "Historical arguments about {option}"]}}, "question": "Report B copies Report A. Both agree about an event. A third, independent account disagrees.\n\n(a) Explain why agreement between A and B is not independent corroboration. (2 marks)\n\n(b) Explain how a historian could investigate the disagreement. (1 mark)", "answer": ["A and B share an evidential origin, so their agreement is not two independent confirmations. Examine provenance, access to the event, purpose, chronology and specific claims; compare with further independent evidence. The third source is not automatically correct merely because it is independent. Weigh evidence rather than decide by a source-count majority."], "points": [{"text": "Recognises dependence of A and B", "marks": 1}, {"text": "Explains its effect on corroboration", "marks": 1}, {"text": "Proposes appropriate evaluation/cross-checking", "marks": 1}], "marks": 3, "stimulus": "Hypothetical source-skills exercise; apply this method to the authentic sources and topic supplied by your teacher.", "table": null, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_ancient_history_25_syll.pdf"}], "partMarks": [2, 1]}, {"id": "modern_history-source-purpose", "template": "source-purpose", "subject": "modern_history", "title": "Purpose and usefulness", "scopes": {"ea": {"route": "modern_history", "topics": ["Historical perspectives on {option}", "Source usefulness and reliability for {option}", "Corroborating evidence about {option}"]}}, "question": "Refer to the hypothetical source description.\n\n(a) Explain one use of the source for a historical inquiry. (1 mark)\n\n(b) Explain one limitation of the source. (1 mark)\n\n(c) Identify another source that could test its claim and explain its use. (1 mark)", "answer": ["It could show how the leader wanted an audience to understand the event and what image the regime promoted. Its persuasive public purpose means it may omit defeats or exaggerate support; it cannot alone establish unanimous approval. An independently produced contemporary account, material evidence or records of opponents could corroborate or challenge the claim. Usefulness depends on the inquiry, rather than a source being simply “good” or “bad”."], "points": [{"text": "Usefulness linked to purpose/perspective", "marks": 1}, {"text": "Limitation linked to the claim", "marks": 1}, {"text": "Suitable corroborating source and purpose", "marks": 1}], "marks": 3, "stimulus": "Hypothetical source-skills exercise, not an authentic historical quotation or evidence about your selected topic. A public statement commissioned by a ruler soon after a disputed event claims that everyone supported the ruler. It was displayed prominently for the ruler’s subjects to read.", "table": null, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_modern_history_25_syll.pdf"}], "partMarks": [1, 1, 1]}, {"id": "modern_history-corroboration", "template": "corroboration", "subject": "modern_history", "title": "Agreement is not independence", "scopes": {"ea": {"route": "modern_history", "topics": ["Source usefulness and reliability for {option}", "Corroborating evidence about {option}", "Historical arguments about {option}"]}}, "question": "Report B copies Report A. Both agree about an event. A third, independent account disagrees.\n\n(a) Explain why agreement between A and B is not independent corroboration. (2 marks)\n\n(b) Explain how a historian could investigate the disagreement. (1 mark)", "answer": ["A and B share an evidential origin, so their agreement is not two independent confirmations. Examine provenance, access to the event, purpose, chronology and specific claims; compare with further independent evidence. The third source is not automatically correct merely because it is independent. Weigh evidence rather than decide by a source-count majority."], "points": [{"text": "Recognises dependence of A and B", "marks": 1}, {"text": "Explains its effect on corroboration", "marks": 1}, {"text": "Proposes appropriate evaluation/cross-checking", "marks": 1}], "marks": 3, "stimulus": "Hypothetical source-skills exercise; apply this method to the authentic sources and topic supplied by your teacher.", "table": null, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_modern_history_25_syll.pdf"}], "partMarks": [2, 1]}, {"id": "atsi_studies-referendum", "template": "referendum", "subject": "atsi_studies", "title": "What changed in 1967?", "scopes": {"unit3": {"route": "atsi_studies", "topics": ["Rights and freedoms: historical context", "Responses to government policies and restrictions"]}, "ea": {"route": "atsi_studies", "topics": ["Recognition and reconciliation", "Historical policies and reconciliation"]}}, "question": "Explain how the 1967 referendum changed the Australian Constitution. Distinguish these changes from the extension of federal voting rights in 1962.", "answer": ["Federal voting eligibility had been extended to all Aboriginal and Torres Strait Islander adults in 1962. The 1967 referendum removed the exclusion of Aboriginal people from the Commonwealth’s race power in section 51(xxvi) and repealed section 127, which excluded Aboriginal people from population reckoning for constitutional purposes. It did not itself grant the federal vote."], "points": [{"text": "Identifies the earlier 1962 federal change", "marks": 1}, {"text": "Explains the Commonwealth legislative-power change", "marks": 1}, {"text": "Explains repeal of section 127", "marks": 1}], "marks": 3, "stimulus": "", "table": null, "difficulty": "medium", "kind": "worked", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_atsi_studies_25_syll.pdf"}, {"label": "Concept reference", "url": "https://aiatsis.gov.au/explore/1967-referendum"}, {"label": "Concept reference", "url": "https://aiatsis.gov.au/explore/right-vote"}]}, {"id": "atsi_studies-participation", "template": "participation", "subject": "atsi_studies", "title": "Evaluate a proposed response", "scopes": {"unit3": {"route": "atsi_studies", "topics": ["Advocacy, resistance and self-determination", "Interpreting sources and perspectives on rights and freedoms"]}, "ea": {"route": "atsi_studies", "topics": ["Evaluating reconciliation responses"]}}, "question": "Refer to the proposed cultural program.\n\n(a) Explain one concern about self-determination. (1 mark)\n\n(b) Use one detail from the stimulus to support your explanation. (1 mark)\n\n(c) Recommend one change and justify how it would support self-determination. (2 marks)", "answer": ["The proposal is being decided for the community without meaningful participation, limiting community control over priorities. Include community-selected representatives with real decision-making authority from planning through evaluation, and fund accessible consultation on community terms. The 18 expressions of interest suggest a basis for participation, but they do not prove all community members share one view."], "points": [{"text": "Explains decision-making/self-determination concern", "marks": 1}, {"text": "Uses the supplied participation evidence", "marks": 1}, {"text": "Specific improvement with rationale", "marks": 2}], "marks": 4, "stimulus": "Fictional practice scenario, not a case study of an actual community: An agency drafts a local cultural program without speaking with the relevant Aboriginal community. Eighteen community members have asked to help shape the program. The agency plans one information meeting after all major decisions are final.", "table": null, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_atsi_studies_25_syll.pdf"}], "partMarks": [1, 1, 2]}, {"id": "study_religion-justice-source", "template": "justice-source", "subject": "study_religion", "title": "Teaching and social action", "scopes": {"ea": {"route": "study_religion", "topics": ["Religious organisations and social justice", "Religious perspectives and human rights", "Evaluating religious influence"]}}, "question": "Refer to the organisation’s statement.\n\n(a) Explain how its stated belief informs its action. (2 marks)\n\n(b) Explain one limitation of using this statement to draw conclusions about all adherents. (1 mark)", "answer": ["The statement treats human dignity as a reason to provide practical support irrespective of background. The meal service translates that stated value into action. This evidence supports an interpretation of this organisation’s response; it does not establish what all adherents believe or do. Analysis of a real tradition requires its authentic teachings and context."], "points": [{"text": "Identifies value of human dignity", "marks": 1}, {"text": "Explains link between value and practical action", "marks": 1}, {"text": "Recognises limits on generalisation", "marks": 1}], "marks": 3, "stimulus": "Original fictional source-skills exercise, not a sacred text or a statement from a real religion: “Our belief in the dignity of every person leads us to offer free meals to anyone who needs one, whatever their background.”", "table": null, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_study_religion_25_syll.pdf"}], "partMarks": [2, 1]}, {"id": "study_religion-evaluate", "template": "evaluate", "subject": "study_religion", "title": "Evaluate an organisation’s response", "scopes": {"ea": {"route": "study_religion", "topics": ["Religious organisations and social justice", "Evaluating religious influence"]}}, "question": "Refer to the organisation’s program data.\n\n(a) Distinguish an output from an outcome, using the data. (2 marks)\n\n(b) Identify one barrier to accessibility. (1 mark)\n\n(c) Recommend and justify one improvement, including how it could be evaluated. (2 marks)", "answer": ["Providing 600 meals is an output: an activity delivered. Whether food insecurity decreased would be an outcome and requires further evidence. The limited opening time and travel difficulty indicate access barriers. An evening session, transport support or an additional location could improve accessibility; evaluate take-up and recipient-reported access, while considering cost and staffing."], "points": [{"text": "Correct output/outcome distinction", "marks": 2}, {"text": "Uses an accessibility barrier", "marks": 1}, {"text": "Justified improvement with evaluation measure", "marks": 2}], "marks": 5, "stimulus": "Fictional data for source analysis: A religious aid organisation provides 600 meals in a month. It opens only from 12–1 pm on weekdays. Some potential recipients report being unable to travel to the venue. No information on change in household food insecurity is supplied.", "table": null, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_study_religion_25_syll.pdf"}], "partMarks": [2, 1, 2]}, {"id": "chinese-leisure-reading", "template": "leisure-reading", "subject": "chinese", "title": "Read for details and a reason", "scopes": {"unit3": {"route": "chinese-ia1", "topics": ["Lifestyles, leisure and cultural perspectives", "Reading and listening: purpose, audience, tone and evidence"]}}, "question": "Read the original practice text. In English, identify TWO activities the speaker does on Saturdays and explain why the speaker likes the arrangement.", "answer": ["The speaker plays basketball with friends and goes to the library afterwards. The arrangement is liked because it allows both physical exercise and study. An answer should convey meaning accurately; it need not use these exact words."], "points": [{"text": "Basketball with friends", "marks": 1}, {"text": "Going to the library after sport", "marks": 1}, {"text": "Explains both exercise and study as the reason", "marks": 2}], "marks": 4, "stimulus": "Original written comprehension practice (not listening audio):\n我星期六常常和朋友一起打篮球。运动以后，我们去图书馆。我喜欢这个安排，因为既能锻炼身体，又能学习。", "table": null, "difficulty": "easy", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_chinese_25_syll.pdf"}]}, {"id": "chinese-future-reading", "template": "future-reading", "subject": "chinese", "title": "Plans and mixed feelings", "scopes": {"ea": {"route": "chinese", "topics": ["Post-school plans and aspirations", "Employment and further study", "Tone, purpose and audience in future-choice texts"]}}, "question": "Read the original practice text. In English, identify the speaker’s study plan and preparation. Explain the speaker’s mixed feelings using two details.", "answer": ["The speaker wants to study engineering at university next year and revises mathematics every week to prepare. The speaker is a little worried about exams but also looks forward to a new life. Both concern and anticipation are needed to explain the mixed feelings."], "points": [{"text": "Engineering at university next year", "marks": 1}, {"text": "Weekly maths revision", "marks": 1}, {"text": "Concern about exams supported by text", "marks": 1}, {"text": "Positive anticipation of new life supported by text", "marks": 1}], "marks": 4, "stimulus": "Original written comprehension practice (not listening audio):\n我明年想在大学学习工程。为了准备，我每周复习数学。我有一点担心考试，但是也很期待新的生活。", "table": null, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_chinese_25_syll.pdf"}]}, {"id": "french-leisure-reading", "template": "leisure-reading", "subject": "french", "title": "Read for details and a reason", "scopes": {"unit3": {"route": "french-ia1", "topics": ["Lifestyles, leisure and cultural perspectives", "Reading and listening: purpose, audience, tone and evidence"]}}, "question": "Read the original practice text. In English, identify TWO activities the speaker does on Saturdays and explain why the speaker likes the arrangement.", "answer": ["The speaker plays basketball with friends and goes to the library afterwards. The arrangement is liked because it allows both physical exercise and study. An answer should convey meaning accurately; it need not use these exact words."], "points": [{"text": "Basketball with friends", "marks": 1}, {"text": "Going to the library after sport", "marks": 1}, {"text": "Explains both exercise and study as the reason", "marks": 2}], "marks": 4, "stimulus": "Original written comprehension practice (not listening audio):\nLe samedi, je joue souvent au basket avec mes amis. Après le sport, nous allons à la bibliothèque. Ce programme me plaît parce que je peux faire de l’exercice et étudier.", "table": null, "difficulty": "easy", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_french_25_syll.pdf"}]}, {"id": "french-future-reading", "template": "future-reading", "subject": "french", "title": "Plans and mixed feelings", "scopes": {"ea": {"route": "french", "topics": ["Post-school plans and aspirations", "Employment and further study", "Tone, purpose and audience in future-choice texts"]}}, "question": "Read the original practice text. In English, identify the speaker’s study plan and preparation. Explain the speaker’s mixed feelings using two details.", "answer": ["The speaker wants to study engineering at university next year and revises mathematics every week to prepare. The speaker is a little worried about exams but also looks forward to a new life. Both concern and anticipation are needed to explain the mixed feelings."], "points": [{"text": "Engineering at university next year", "marks": 1}, {"text": "Weekly maths revision", "marks": 1}, {"text": "Concern about exams supported by text", "marks": 1}, {"text": "Positive anticipation of new life supported by text", "marks": 1}], "marks": 4, "stimulus": "Original written comprehension practice (not listening audio):\nL’année prochaine, je voudrais étudier l’ingénierie à l’université. Pour me préparer, je révise les maths chaque semaine. Les examens m’inquiètent un peu, mais j’ai aussi hâte de découvrir une nouvelle vie.", "table": null, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_french_25_syll.pdf"}]}, {"id": "german-leisure-reading", "template": "leisure-reading", "subject": "german", "title": "Read for details and a reason", "scopes": {"unit3": {"route": "german-ia1", "topics": ["Lifestyles, leisure and cultural perspectives", "Reading and listening: purpose, audience, tone and evidence"]}}, "question": "Read the original practice text. In English, identify TWO activities the speaker does on Saturdays and explain why the speaker likes the arrangement.", "answer": ["The speaker plays basketball with friends and goes to the library afterwards. The arrangement is liked because it allows both physical exercise and study. An answer should convey meaning accurately; it need not use these exact words."], "points": [{"text": "Basketball with friends", "marks": 1}, {"text": "Going to the library after sport", "marks": 1}, {"text": "Explains both exercise and study as the reason", "marks": 2}], "marks": 4, "stimulus": "Original written comprehension practice (not listening audio):\nSamstags spiele ich oft mit meinen Freunden Basketball. Nach dem Sport gehen wir in die Bibliothek. Ich mag diesen Plan, weil ich mich bewegen und lernen kann.", "table": null, "difficulty": "easy", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_german_25_syll.pdf"}]}, {"id": "german-future-reading", "template": "future-reading", "subject": "german", "title": "Plans and mixed feelings", "scopes": {"ea": {"route": "german", "topics": ["Post-school plans and aspirations", "Employment and further study", "Tone, purpose and audience in future-choice texts"]}}, "question": "Read the original practice text. In English, identify the speaker’s study plan and preparation. Explain the speaker’s mixed feelings using two details.", "answer": ["The speaker wants to study engineering at university next year and revises mathematics every week to prepare. The speaker is a little worried about exams but also looks forward to a new life. Both concern and anticipation are needed to explain the mixed feelings."], "points": [{"text": "Engineering at university next year", "marks": 1}, {"text": "Weekly maths revision", "marks": 1}, {"text": "Concern about exams supported by text", "marks": 1}, {"text": "Positive anticipation of new life supported by text", "marks": 1}], "marks": 4, "stimulus": "Original written comprehension practice (not listening audio):\nNächstes Jahr möchte ich an der Universität Ingenieurwissenschaften studieren. Zur Vorbereitung wiederhole ich jede Woche Mathematik. Ich mache mir etwas Sorgen wegen der Prüfungen, freue mich aber auch auf das neue Leben.", "table": null, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_german_25_syll.pdf"}]}, {"id": "italian-leisure-reading", "template": "leisure-reading", "subject": "italian", "title": "Read for details and a reason", "scopes": {"unit3": {"route": "italian-ia1", "topics": ["Lifestyles, leisure and cultural perspectives", "Reading and listening: purpose, audience, tone and evidence"]}}, "question": "Read the original practice text. In English, identify TWO activities the speaker does on Saturdays and explain why the speaker likes the arrangement.", "answer": ["The speaker plays basketball with friends and goes to the library afterwards. The arrangement is liked because it allows both physical exercise and study. An answer should convey meaning accurately; it need not use these exact words."], "points": [{"text": "Basketball with friends", "marks": 1}, {"text": "Going to the library after sport", "marks": 1}, {"text": "Explains both exercise and study as the reason", "marks": 2}], "marks": 4, "stimulus": "Original written comprehension practice (not listening audio):\nIl sabato gioco spesso a pallacanestro con i miei amici. Dopo lo sport andiamo in biblioteca. Mi piace questo programma perché posso fare movimento e studiare.", "table": null, "difficulty": "easy", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_italian_25_syll.pdf"}]}, {"id": "italian-future-reading", "template": "future-reading", "subject": "italian", "title": "Plans and mixed feelings", "scopes": {"ea": {"route": "italian", "topics": ["Post-school plans and aspirations", "Employment and further study", "Tone, purpose and audience in future-choice texts"]}}, "question": "Read the original practice text. In English, identify the speaker’s study plan and preparation. Explain the speaker’s mixed feelings using two details.", "answer": ["The speaker wants to study engineering at university next year and revises mathematics every week to prepare. The speaker is a little worried about exams but also looks forward to a new life. Both concern and anticipation are needed to explain the mixed feelings."], "points": [{"text": "Engineering at university next year", "marks": 1}, {"text": "Weekly maths revision", "marks": 1}, {"text": "Concern about exams supported by text", "marks": 1}, {"text": "Positive anticipation of new life supported by text", "marks": 1}], "marks": 4, "stimulus": "Original written comprehension practice (not listening audio):\nL’anno prossimo vorrei studiare ingegneria all’università. Per prepararmi ripasso matematica ogni settimana. Gli esami mi preoccupano un po’, ma non vedo l’ora di iniziare una nuova vita.", "table": null, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_italian_25_syll.pdf"}]}, {"id": "japanese-leisure-reading", "template": "leisure-reading", "subject": "japanese", "title": "Read for details and a reason", "scopes": {"unit3": {"route": "japanese-ia1", "topics": ["Lifestyles, leisure and cultural perspectives", "Reading and listening: purpose, audience, tone and evidence"]}}, "question": "Read the original practice text. In English, identify TWO activities the speaker does on Saturdays and explain why the speaker likes the arrangement.", "answer": ["The speaker plays basketball with friends and goes to the library afterwards. The arrangement is liked because it allows both physical exercise and study. An answer should convey meaning accurately; it need not use these exact words."], "points": [{"text": "Basketball with friends", "marks": 1}, {"text": "Going to the library after sport", "marks": 1}, {"text": "Explains both exercise and study as the reason", "marks": 2}], "marks": 4, "stimulus": "Original written comprehension practice (not listening audio):\n土曜日はよく友達とバスケットボールをします。スポーツの後で、図書館に行きます。運動も勉強もできるので、この予定が好きです。", "table": null, "difficulty": "easy", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_japanese_25_syll.pdf"}]}, {"id": "japanese-future-reading", "template": "future-reading", "subject": "japanese", "title": "Plans and mixed feelings", "scopes": {"ea": {"route": "japanese", "topics": ["Post-school plans and aspirations", "Employment and further study", "Tone, purpose and audience in future-choice texts"]}}, "question": "Read the original practice text. In English, identify the speaker’s study plan and preparation. Explain the speaker’s mixed feelings using two details.", "answer": ["The speaker wants to study engineering at university next year and revises mathematics every week to prepare. The speaker is a little worried about exams but also looks forward to a new life. Both concern and anticipation are needed to explain the mixed feelings."], "points": [{"text": "Engineering at university next year", "marks": 1}, {"text": "Weekly maths revision", "marks": 1}, {"text": "Concern about exams supported by text", "marks": 1}, {"text": "Positive anticipation of new life supported by text", "marks": 1}], "marks": 4, "stimulus": "Original written comprehension practice (not listening audio):\n来年、大学で工学を勉強したいです。準備のために、毎週数学を復習しています。試験は少し心配ですが、新しい生活も楽しみです。", "table": null, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_japanese_25_syll.pdf"}]}, {"id": "spanish-leisure-reading", "template": "leisure-reading", "subject": "spanish", "title": "Read for details and a reason", "scopes": {"unit3": {"route": "spanish-ia1", "topics": ["Lifestyles, leisure and cultural perspectives", "Reading and listening: purpose, audience, tone and evidence"]}}, "question": "Read the original practice text. In English, identify TWO activities the speaker does on Saturdays and explain why the speaker likes the arrangement.", "answer": ["The speaker plays basketball with friends and goes to the library afterwards. The arrangement is liked because it allows both physical exercise and study. An answer should convey meaning accurately; it need not use these exact words."], "points": [{"text": "Basketball with friends", "marks": 1}, {"text": "Going to the library after sport", "marks": 1}, {"text": "Explains both exercise and study as the reason", "marks": 2}], "marks": 4, "stimulus": "Original written comprehension practice (not listening audio):\nLos sábados suelo jugar al baloncesto con mis amigos. Después del deporte vamos a la biblioteca. Me gusta este plan porque puedo hacer ejercicio y estudiar.", "table": null, "difficulty": "easy", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_spanish_25_syll.pdf"}]}, {"id": "spanish-future-reading", "template": "future-reading", "subject": "spanish", "title": "Plans and mixed feelings", "scopes": {"ea": {"route": "spanish", "topics": ["Post-school plans and aspirations", "Employment and further study", "Tone, purpose and audience in future-choice texts"]}}, "question": "Read the original practice text. In English, identify the speaker’s study plan and preparation. Explain the speaker’s mixed feelings using two details.", "answer": ["The speaker wants to study engineering at university next year and revises mathematics every week to prepare. The speaker is a little worried about exams but also looks forward to a new life. Both concern and anticipation are needed to explain the mixed feelings."], "points": [{"text": "Engineering at university next year", "marks": 1}, {"text": "Weekly maths revision", "marks": 1}, {"text": "Concern about exams supported by text", "marks": 1}, {"text": "Positive anticipation of new life supported by text", "marks": 1}], "marks": 4, "stimulus": "Original written comprehension practice (not listening audio):\nEl año que viene me gustaría estudiar ingeniería en la universidad. Para prepararme, repaso matemáticas cada semana. Los exámenes me preocupan un poco, pero también tengo ganas de empezar una nueva vida.", "table": null, "difficulty": "medium", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_spanish_25_syll.pdf"}]}, {"id": "chinese_ext-perspective-reading", "template": "perspective-reading", "subject": "chinese_ext", "title": "Analyse a qualified viewpoint", "scopes": {"unit3": {"route": "chinese_ext-ia1", "topics": ["Interpreting attitudes, perspectives and values", "Analysing how language and textual conventions shape meaning", "Synthesising evidence and constructing arguments"]}}, "question": "Analyse how the original written text presents technology. In your course language, explain the viewpoint and the effect of one contrast. The model below explains the ideas in English so you can check meaning; it is not a model of target-language expression.", "answer": ["The viewpoint is qualified: technology enables contact across distance but may reduce interaction with people nearby. The contrast between bringing distant friends closer and distancing the person beside us highlights this tension. The final sentence places responsibility on how people use technology rather than treating technology as inherently good or bad. In the course language, support the analysis with a relevant phrase, such as “随时…联系”与“不再交谈”."], "points": [{"text": "Recognises qualified rather than wholly positive/negative viewpoint", "marks": 1}, {"text": "Analyses the contrast using a textual detail", "marks": 2}, {"text": "Explains responsibility/use in the final sentence", "marks": 1}], "marks": 4, "stimulus": "Original written analysis practice; no audio component supplied:\n手机让我们随时与远方的朋友联系，却也可能让同桌的人不再交谈。技术并没有替我们决定怎样生活；关键在于我们怎样使用它。", "table": null, "difficulty": "hard", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_chinese_ext_26_syll.pdf"}]}, {"id": "french_ext-perspective-reading", "template": "perspective-reading", "subject": "french_ext", "title": "Analyse a qualified viewpoint", "scopes": {"unit3": {"route": "french_ext-ia1", "topics": ["Interpreting attitudes, perspectives and values", "Analysing how language and textual conventions shape meaning", "Synthesising evidence and constructing arguments"]}}, "question": "Analyse how the original written text presents technology. In your course language, explain the viewpoint and the effect of one contrast. The model below explains the ideas in English so you can check meaning; it is not a model of target-language expression.", "answer": ["The viewpoint is qualified: technology enables contact across distance but may reduce interaction with people nearby. The contrast between bringing distant friends closer and distancing the person beside us highlights this tension. The final sentence places responsibility on how people use technology rather than treating technology as inherently good or bad. In the course language, support the analysis with a relevant phrase, such as “nous rapproche” / “nous éloigner”."], "points": [{"text": "Recognises qualified rather than wholly positive/negative viewpoint", "marks": 1}, {"text": "Analyses the contrast using a textual detail", "marks": 2}, {"text": "Explains responsibility/use in the final sentence", "marks": 1}], "marks": 4, "stimulus": "Original written analysis practice; no audio component supplied:\nLe téléphone nous rapproche de nos amis lointains, mais il peut aussi nous éloigner de la personne assise à côté de nous. La technologie ne choisit pas notre vie à notre place : tout dépend de l’usage que nous en faisons.", "table": null, "difficulty": "hard", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_french_ext_25_syll.pdf"}]}, {"id": "german_ext-perspective-reading", "template": "perspective-reading", "subject": "german_ext", "title": "Analyse a qualified viewpoint", "scopes": {"unit3": {"route": "german_ext-ia1", "topics": ["Interpreting attitudes, perspectives and values", "Analysing how language and textual conventions shape meaning", "Synthesising evidence and constructing arguments"]}}, "question": "Analyse how the original written text presents technology. In your course language, explain the viewpoint and the effect of one contrast. The model below explains the ideas in English so you can check meaning; it is not a model of target-language expression.", "answer": ["The viewpoint is qualified: technology enables contact across distance but may reduce interaction with people nearby. The contrast between bringing distant friends closer and distancing the person beside us highlights this tension. The final sentence places responsibility on how people use technology rather than treating technology as inherently good or bad. In the course language, support the analysis with a relevant phrase, such as “näher” / “entfernen”."], "points": [{"text": "Recognises qualified rather than wholly positive/negative viewpoint", "marks": 1}, {"text": "Analyses the contrast using a textual detail", "marks": 2}, {"text": "Explains responsibility/use in the final sentence", "marks": 1}], "marks": 4, "stimulus": "Original written analysis practice; no audio component supplied:\nDas Handy bringt uns weit entfernten Freunden näher, kann uns aber zugleich von der Person neben uns entfernen. Die Technik entscheidet nicht für uns, wie wir leben; entscheidend ist, wie wir sie nutzen.", "table": null, "difficulty": "hard", "kind": "model", "pitfall": "Check that every part of the question has been answered and that claims use the supplied evidence.", "sources": [{"label": "QCAA syllabus and assessment scope", "url": "https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_german_ext_26_syll.pdf"}]}]};
